/**
 * CookieBanner â GDPR/cookie consent banner.
 * One-time display on first visit, stored in localStorage under 'tv-clone-cookie-acked'.
 * Both "Accept" and "Reject" dismiss the banner permanently.
 *
 * Sets `--cookie-banner-offset` CSS variable on <html> so other fixed-position
 * elements (e.g. UnsupportedFeatureToast) can avoid overlapping the banner.
 */

import { useEffect, useRef } from 'react';
import { useCookieBanner } from '@shared/hooks/useCookieBanner';

export function CookieBanner() {
  const { show, accept, reject } = useCookieBanner();
  const ref = useRef<HTMLDivElement>(null);

  // Measure banner height and set CSS variable for other components to use
  useEffect(() => {
    if (!show) {
      document.documentElement.style.removeProperty('--cookie-banner-offset');
      return;
    }
    // Use ResizeObserver to handle dynamic height changes
    const el = ref.current;
    if (!el) return;
    const updateOffset = () => {
      const h = el.getBoundingClientRect().height;
      document.documentElement.style.setProperty('--cookie-banner-offset', `${h + 16}px`);
    };
    updateOffset();
    const observer = new ResizeObserver(updateOffset);
    observer.observe(el);
    return () => {
      observer.disconnect();
      document.documentElement.style.removeProperty('--cookie-banner-offset');
    };
  }, [show]);

  if (!show) return null;

  return (
    <div
      ref={ref}
      data-testid="cookie-banner"
      style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        zIndex: 400,
        backgroundColor: 'var(--tv-panel-bg, #1e222d)',
        color: 'var(--tv-text, #d1d4dc)',
        borderTop: '1px solid var(--tv-border, #2a2e39)',
        padding: '12px 24px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 16,
        flexWrap: 'wrap' as const,
        boxShadow: '0 -2px 10px rgba(0,0,0,0.2)',
      }}
    >
      <div style={{ fontSize: 13, lineHeight: 1.5, flex: 1, minWidth: 200 }}>
        We use cookies to improve your experience. By continuing to use this site, you agree to our cookie policy.
      </div>
      <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
        <button
          data-testid="cookie-accept"
          onClick={accept}
          style={{
            padding: '6px 16px',
            backgroundColor: 'var(--tv-accent, #2962FF)',
            color: '#ffffff',
            border: 'none',
            borderRadius: 4,
            fontSize: 13,
            fontWeight: 600,
            cursor: 'pointer',
          }}
        >
          Accept
        </button>
        <button
          data-testid="cookie-reject"
          onClick={reject}
          style={{
            padding: '6px 16px',
            backgroundColor: 'transparent',
            color: 'var(--tv-text-muted, #787b86)',
            border: '1px solid var(--tv-border, #2a2e39)',
            borderRadius: 4,
            fontSize: 13,
            cursor: 'pointer',
          }}
        >
          Reject
        </button>
      </div>
    </div>
  );
}

