}

/* Light theme */
.chart-workspace-root[data-theme='light'] {
  --chart-bg: #ffffff;
  --chart-panel: #f0f3fa;
  --chart-text: #131722;
  --chart-text-muted: #787b86;
  --chart-accent: #2962ff;
  --chart-positive: #26a69a;
  --chart-negative: #ef5350;
