/* âââ Chart Workspace Shell â 7-Region CSS Grid ââââââââââââââââââââââââââââ */

.chart-workspace-root {
  height: 100%;
  overflow: hidden;
}

.chart-workspace-shell {
  display: grid;
  grid-template-columns: auto 1fr 250px;
  grid-template-rows: auto auto 1fr auto;
  grid-template-areas:
    'header  header  header'
    'toolbar toolbar sidebar'
    'left    chart   sidebar'
    'left    bottom  bottom';
  height: 100%;
  min-height: 0;
}

/* ââ Responsive: Medium width (768â1199px) ââââââââââââââââââââââââââââââââââ */

.chart-workspace-shell[data-breakpoint='medium'] {
  grid-template-columns: auto 1fr 200px;
}

/* ââ Responsive: Narrow width (<768px) ââââââââââââââââââââââââââââââââââââââ */

.chart-workspace-shell[data-breakpoint='narrow'] {
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto 1fr;
  grid-template-areas:
    'header  header'
    'toolbar toolbar'
    'left    chart';
}

/* At narrow width, sidebar and bottom panel are removed from grid flow
   and rendered as overlay drawers instead */

/* Grid region placement */
.chart-shell__region--header {
  grid-area: header;
}

.chart-shell__region--toolbar {
  grid-area: toolbar;
}

.chart-shell__region--left-toolbar {
  grid-area: left;
}

.chart-shell__region--chart {
  grid-area: chart;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.chart-shell__region--sidebar {
  grid-area: sidebar;
  min-height: 0;
  overflow: hidden;
}

.chart-shell__region--bottom {
  grid-area: bottom;
  min-height: 0;
}

/* Common region styling */
.chart-shell__region {
  background-color: var(--chart-panel);
  border-color: var(--chart-border);
}

/* Chart canvas region gets the dominant background */
.chart-shell__region--chart {
  background-color: var(--chart-bg);
}

/* Header and toolbar regions */
.chart-shell__region--header,
.chart-shell__region--toolbar {
  border-bottom: 1px solid var(--chart-divider);
}

/* Left toolbar border */
.chart-shell__region--left-toolbar {
  border-right: 1px solid var(--chart-divider);
}

/* Sidebar border */
.chart-shell__region--sidebar {
  border-left: 1px solid var(--chart-divider);
}

/* âââ Responsive Sidebar Drawer (narrow breakpoint) ââââââââââââââââââââââââââ */

.chart-sidebar-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 280px;
  max-width: 85vw;
  z-index: 180;
  background-color: var(--chart-panel);
  border-left: 1px solid var(--chart-divider);
  box-shadow: -4px 0 20px rgba(0, 0, 0, 0.3);
  transform: translateX(100%);
  transition: transform 0.25s ease-out;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.chart-sidebar-drawer--open {
  transform: translateX(0);
}

.chart-sidebar-drawer__backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 179;
  background-color: rgba(0, 0, 0, 0.4);
  animation: drawer-backdrop-in 0.2s ease-out;
}

@keyframes drawer-backdrop-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Bottom panel top border */
.chart-shell__region--bottom {
  border-top: 1px solid var(--chart-divider);
}

/* âââ Responsive Bottom Panel Drawer (narrow breakpoint) ââââââââââââââââââââââ */

.chart-bottom-drawer {
  position: fixed;
