  transform: translateY(100%);
  transition: transform 0.25s ease-out;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.chart-bottom-drawer--open {
  transform: translateY(0);
}

.chart-bottom-drawer__backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 179;
  background-color: rgba(0, 0, 0, 0.4);
  animation: drawer-backdrop-in 0.2s ease-out;
}

/* âââ Responsive Toggle Buttons (narrow/medium breakpoints) âââââââââââââââââââ */

.chart-resp-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: none;
