.chart-workspace-shell[data-breakpoint='narrow'] .toolbar-overflow-btn {
  display: inline-flex;
}

/* âââ Left Drawing Toolbar responsive âââââââââââââââââââââââââââââââââââââââââ */

/* At narrow width, drawing toolbar collapses to narrower icons */
.chart-workspace-shell[data-breakpoint='narrow'] .drawing-toolbar {
  width: 32px;
  padding: 2px 0;
}

.chart-workspace-shell[data-breakpoint='narrow'] .drawing-toolbar__btn {
  width: 28px;
