/* âââ Sidebar responsive width ââââââââââââââââââââââââââââââââââââââââââââââââ */

.chart-workspace-shell[data-breakpoint='medium'] .chart-shell__region--sidebar {
  overflow: hidden;
}

/* âââ Responsive toggle strip (in chart viewport region for narrow) âââââââââââ */

.chart-resp-toggle-strip {
  display: none;
  position: absolute;
