}

/* âââ Header responsive ââââââââââââââââââââââââââââââââââââââââââââââââââââââ */

.chart-workspace-shell[data-breakpoint='narrow'] .top-header-bar {
  padding: 0 4px;
}

.chart-workspace-shell[data-breakpoint='narrow'] .top-header-bar__brand-name {
