}

.chart-workspace-shell[data-breakpoint='medium'] .header-dropdown--compact .header-dropdown__trigger {
  padding: 0 2px;
  font-size: 10px;
}

/* âââ Overlay Host ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ */

.chart-overlay-host {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  z-index: 100;
}

/* Allow children of overlay host to receive pointer events */
.chart-overlay-host > * {
  pointer-events: auto;
}

/* âââ Instrument Toolbar âââââââââââââââââââââââââââââââââââââââââââââââââââââ */

.instrument-toolbar {
  display: flex;
