/* âââ Pine Editor âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ */

.pine-editor {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 200px;
}

.pine-editor__toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-bottom: 1px solid var(--chart-divider);
  flex-wrap: wrap;
}

.pine-editor__toolbar-separator {
  width: 1px;
  height: 18px;
  background-color: var(--chart-divider);
  margin: 0 4px;
}

.pine-editor__btn {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border: 1px solid var(--chart-divider);
  border-radius: 4px;
  background: transparent;
  color: var(--chart-text);
  cursor: pointer;
  font-size: 11px;
  font-weight: 500;
  transition: background-color 0.15s, border-color 0.15s;
}

.pine-editor__btn:hover {
  background-color: var(--chart-divider);
}

.pine-editor__btn--primary {
  background-color: var(--chart-accent);
  border-color: var(--chart-accent);
  color: #ffffff;
}

.pine-editor__btn--primary:hover {
  opacity: 0.9;
}

.pine-editor__btn--compiling {
  opacity: 0.6;
  cursor: wait;
}

.pine-editor__btn--error {
  border-color: #ef5350;
  color: #ef5350;
}

.pine-editor__notice {
  font-size: 10px;
  color: var(--chart-text-muted);
  margin-left: auto;
  opacity: 0.6;
}

.pine-editor__body {
  flex: 1;
  min-height: 0;
  display: flex;
}

.pine-editor__textarea {
  width: 100%;
  height: 100%;
  resize: none;
  border: none;
  outline: none;
  padding: 8px 12px;
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
  font-size: 12px;
  line-height: 1.5;
  tab-size: 2;
  color: var(--chart-text);
  background-color: transparent;
}

.chart-workspace-root[data-theme='dark'] .pine-editor__textarea {
  background-color: #1e222d;
  color: #d1d4dc;
}

.chart-workspace-root[data-theme='light'] .pine-editor__textarea {
  background-color: #ffffff;
  color: #131722;
}

.pine-editor__output {
  border-top: 1px solid var(--chart-divider);
  padding: 6px 12px;
  max-height: 80px;
  overflow-y: auto;
  font-size: 11px;
}

.pine-editor__output--error {
  background-color: rgba(239, 83, 80, 0.1);
  border-top-color: #ef5350;
}

.pine-editor__output--success {
  background-color: rgba(38, 166, 154, 0.1);
  border-top-color: #26a69a;
}

.pine-editor__output-text {
  margin: 0;
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
  font-size: 11px;
  line-height: 1.4;
  color: var(--chart-text-muted);
  white-space: pre-wrap;
  word-break: break-all;
}

.pine-editor__output--error .pine-editor__output-text {
  color: #ef5350;
}

.pine-editor__output--success .pine-editor__output-text {
  color: #26a69a;
}

