/**
 * LeftDrawingToolbar â Vertical toolbar for chart drawing tools.
 *
 * Renders grouped tool families with expandable flyouts instead of a flat
 * button list. Each group shows its primary tool in the collapsed toolbar,
 * with a chevron indicator that expands the flyout panel showing all tools
 * in that group.
 *
 * Below the tool groups, mode operation buttons provide access to:
 * - Magnet mode toggle
 * - Stay-in-drawing mode toggle
 * - Lock all drawings
 * - Hide all drawings
 * - Remove all drawings
 * - Object tree panel access
 *
 * Supported tools activate drawing mode via store.setSelectedTool().
 * Placeholder/premium tools trigger the appropriate boundary system.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { useChartStore } from '@features/chart/store/chart-store';
import {
  DRAWING_TOOL_REGISTRY,
  DRAWING_TOOL_GROUPS,
  getToolsInGroup,
  getPlaceholderFeatureMap,
  type DrawingToolConfig,
} from '@features/chart/registries/drawing-tools';
import type {
  DrawingTool,
  DrawingToolGroup,
  UnsupportedFeature,
} from '@features/chart/types';
import {
  DRAWING_TOOL_ICON_MAP,
  DRAWING_GROUP_ICON_MAP,
  MagnetModeIcon,
  StayInDrawingIcon,
  LockAllIcon,
  HideAllIcon,
  RemoveAllIcon,
  ObjectTreeIcon,
} from './DrawingToolIcons';

/**
 * Individual drawing tool button (used in flyout panels).
 * Handles click behavior: supported tools activate drawing mode,
 * placeholder/premium tools trigger the boundary system.
 */
function DrawingToolButton({
  config,
  isActive,
  onSelect,
  compact = false,
}: {
  config: DrawingToolConfig;
  isActive: boolean;
  onSelect: (tool: DrawingTool) => void;
  compact?: boolean;
}) {
  const openUnsupportedFeature = useChartStore((s) => s.openUnsupportedFeature);
  const placeholderFeatureMap = getPlaceholderFeatureMap();
  const [justClicked, setJustClicked] = useState(false);

  const IconComponent = DRAWING_TOOL_ICON_MAP[config.icon];
  const icon = IconComponent ? <IconComponent /> : null;

  const handleClick = () => {
    setJustClicked(true);
    setTimeout(() => setJustClicked(false), 200);

    switch (config.status) {
      case 'placeholder': {
        const feature = placeholderFeatureMap[config.id];
        if (feature) {
          openUnsupportedFeature(feature as UnsupportedFeature);
        }
        break;
      }
      case 'premium': {
        openUnsupportedFeature(config.id as UnsupportedFeature);
        break;
      }
      case 'supported':
      default: {
        onSelect(config.id as DrawingTool);
        break;
      }
    }
  };

  const isPlaceholder = config.status === 'placeholder' || config.status === 'premium';

  const classes = [
    'drawing-toolbar__btn',
    isActive ? 'drawing-toolbar__btn--active' : '',
    isPlaceholder ? 'drawing-toolbar__btn--placeholder' : '',
    compact ? 'drawing-toolbar__btn--compact' : '',
    justClicked ? 'drawing-toolbar__btn--flash' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button
      type="button"
      className={classes}
      data-testid={config.testId}
      title={config.label}
      aria-label={config.label}
      aria-pressed={isActive}
      onClick={handleClick}
    >
      <span className="drawing-toolbar__btn-icon">{icon}</span>
      {!compact && (
        <span className="drawing-toolbar__btn-label">{config.label}</span>
      )}
    </button>
  );
}

/**
 * Grouped flyout panel that shows all tools in a group.
 * Positioned to the right of the toolbar when a group is expanded.
 */
function DrawingGroupFlyout({
  group,
  selectedTool,
  onSelectTool,
  onClose,
  anchorRef,
}: {
  group: DrawingToolGroup;
  selectedTool: DrawingTool | null;
  onSelectTool: (tool: DrawingTool) => void;
  onClose: () => void;
  anchorRef: React.RefObject<HTMLButtonElement | null>;
}) {
  const flyoutRef = useRef<HTMLDivElement>(null);
  const tools = getToolsInGroup(group);

  // Close on outside click
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (
        flyoutRef.current &&
        !flyoutRef.current.contains(e.target as Node) &&
        anchorRef.current &&
        !anchorRef.current.contains(e.target as Node)
      ) {
        onClose();
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [onClose, anchorRef]);

  // Close on Escape
  useEffect(() => {
    function handleKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose();
    }
    document.addEventListener('keydown', handleKey);
    return () => document.removeEventListener('keydown', handleKey);
  }, [onClose]);

  const groupMeta = DRAWING_TOOL_GROUPS.find((g) => g.id === group);

  return (
    <div
      ref={flyoutRef}
      className="drawing-toolbar__flyout"
      role="menu"
      aria-label={`${groupMeta?.label ?? group} tools`}
      data-testid={`drawing-flyout-${group}`}
    >
      <div className="drawing-toolbar__flyout-header">
        {groupMeta?.label ?? group}
      </div>
      <div className="drawing-toolbar__flyout-tools">
        {tools.map((tool) => (
          <DrawingToolButton
            key={tool.id}
            config={tool}
            isActive={selectedTool === tool.id}
            onSelect={(t) => {
              onSelectTool(t);
              // Close flyout after selecting a supported tool
              if (tool.status === 'supported') onClose();
            }}
          />
        ))}
      </div>
    </div>
  );
}

/**
 * Mode operation toggle button for the bottom section of the toolbar.
 */
function ModeToggleButton({
  label,
  icon,
  isActive,
  onClick,
  testId,
}: {
  label: string;
  icon: React.ReactNode;
  isActive: boolean;
  onClick: () => void;
  testId: string;
}) {
  const classes = [
    'drawing-toolbar__btn',
    'drawing-toolbar__btn--mode',
    isActive ? 'drawing-toolbar__btn--active' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <button
      type="button"
      className={classes}
      data-testid={testId}
      title={label}
      aria-label={label}
      aria-pressed={isActive}
      onClick={onClick}
    >
      <span className="drawing-toolbar__btn-icon">{icon}</span>
    </button>
  );
}

/**
 * Horizontal separator line between sections.
 */
function DrawingToolbarSeparator() {
  return <div className="drawing-toolbar__separator" role="separator" />;
}

export function LeftDrawingToolbar() {
  const selectedTool = useChartStore((s) => s.selectedTool);
  const setSelectedTool = useChartStore((s) => s.setSelectedTool);
  const drawingToolbarState = useChartStore((s) => s.drawingToolbarState);
  const setMagnetMode = useChartStore((s) => s.setMagnetMode);
  const setStayInDrawingMode = useChartStore((s) => s.setStayInDrawingMode);
  const setLockAllDrawings = useChartStore((s) => s.setLockAllDrawings);
  const setHideAllDrawings = useChartStore((s) => s.setHideAllDrawings);
  const removeAllDrawings = useChartStore((s) => s.removeAllDrawings);
  const setActiveGroupFlyout = useChartStore((s) => s.setActiveGroupFlyout);
  const setRightSidebarPanel = useChartStore((s) => s.setRightSidebarPanel);

  const activeFlyout = drawingToolbarState.activeGroupFlyout;
  const groupButtonRefs = useRef<Record<string, HTMLButtonElement | null>>({});

  const handleToolSelect = useCallback(
    (tool: DrawingTool) => {
      // Clicking the already-active non-cursor tool deactivates it
      if (selectedTool === tool && tool !== 'cursor') {
        setSelectedTool('cursor');
      } else {
        setSelectedTool(tool);
      }
    },
    [selectedTool, setSelectedTool],
  );

  const handleGroupClick = useCallback(
    (group: DrawingToolGroup) => {
      if (activeFlyout === group) {
        setActiveGroupFlyout(null);
      } else {
        setActiveGroupFlyout(group);
      }
    },
    [activeFlyout, setActiveGroupFlyout],
  );

  const handleCloseFlyout = useCallback(() => {
    setActiveGroupFlyout(null);
  }, [setActiveGroupFlyout]);

  // Determine which primary tool is active per group (to show active state on group button)
  const getActiveToolInGroup = (group: DrawingToolGroup): DrawingTool | null => {
    if (!selectedTool) return null;
    const toolConfig = DRAWING_TOOL_REGISTRY.find((t) => t.id === selectedTool);
    if (toolConfig && toolConfig.group === group) return selectedTool;
    return null;
  };

  // Build group data with primary tools
  const groupsWithPrimary = DRAWING_TOOL_GROUPS.map((groupDef) => {
    const primaryTool = DRAWING_TOOL_REGISTRY.find(
      (t) => t.group === groupDef.id && t.isGroupPrimary,
    );
    return { ...groupDef, primaryTool };
  });

  return (
    <div
      className="drawing-toolbar"
      role="toolbar"
      aria-label="Drawing tools"
      aria-orientation="vertical"
      data-testid="left-drawing-toolbar"
    >
      {/* Tool group buttons */}
      <div className="drawing-toolbar__groups">
        {groupsWithPrimary.map((groupDef) => {
          const activeToolInGroup = getActiveToolInGroup(groupDef.id);
          const isFlyoutOpen = activeFlyout === groupDef.id;
          const GroupIcon = DRAWING_GROUP_ICON_MAP[groupDef.icon];
          // Show the active tool's icon if one in this group is selected, otherwise group primary
          const activeToolConfig = activeToolInGroup
            ? DRAWING_TOOL_REGISTRY.find((t) => t.id === activeToolInGroup)
            : null;
          const DisplayIcon = activeToolConfig
            ? (DRAWING_TOOL_ICON_MAP[activeToolConfig.icon] ?? GroupIcon)
            : GroupIcon;
          const iconEl = DisplayIcon ? <DisplayIcon /> : null;

          const btnClasses = [
            'drawing-toolbar__btn',
            'drawing-toolbar__btn--group',
            activeToolInGroup ? 'drawing-toolbar__btn--active' : '',
            isFlyoutOpen ? 'drawing-toolbar__btn--flyout-open' : '',
          ]
            .filter(Boolean)
            .join(' ');

          return (
            <div key={groupDef.id} className="drawing-toolbar__group-wrapper">
              <button
                ref={(el) => {
                  groupButtonRefs.current[groupDef.id] = el;
                }}
                type="button"
                className={btnClasses}
                data-testid={`drawing-group-${groupDef.id}`}
                title={groupDef.label}
                aria-label={`${groupDef.label} tools`}
                aria-expanded={isFlyoutOpen}
                aria-haspopup="menu"
                onClick={() => handleGroupClick(groupDef.id)}
              >
                <span className="drawing-toolbar__btn-icon">{iconEl}</span>
                <span className="drawing-toolbar__btn-chevron" aria-hidden="true">
                  â¸
                </span>
              </button>

              {isFlyoutOpen && (
                <DrawingGroupFlyout
                  group={groupDef.id}
                  selectedTool={selectedTool}
                  onSelectTool={handleToolSelect}
                  onClose={handleCloseFlyout}
                  anchorRef={{
                    current: groupButtonRefs.current[groupDef.id] ?? null,
                  }}
                />
              )}
            </div>
          );
        })}
      </div>

      {/* Separator between tool groups and mode operations */}
      <DrawingToolbarSeparator />

      {/* Drawing mode operations */}
      <div className="drawing-toolbar__modes">
        <ModeToggleButton
          label="Magnet Mode"
          icon={<MagnetModeIcon />}
          isActive={drawingToolbarState.magnetMode}
          onClick={() => setMagnetMode(!drawingToolbarState.magnetMode)}
          testId="drawing-mode-magnet"
        />
        <ModeToggleButton
          label="Stay in Drawing Mode"
          icon={<StayInDrawingIcon />}
          isActive={drawingToolbarState.stayInDrawingMode}
          onClick={() => setStayInDrawingMode(!drawingToolbarState.stayInDrawingMode)}
          testId="drawing-mode-stay-in-drawing"
        />
        <ModeToggleButton
          label="Lock All Drawings"
          icon={<LockAllIcon />}
          isActive={drawingToolbarState.lockAllDrawings}
          onClick={() => setLockAllDrawings(!drawingToolbarState.lockAllDrawings)}
          testId="drawing-mode-lock-all"
        />
        <ModeToggleButton
          label="Hide All Drawings"
          icon={<HideAllIcon />}
          isActive={drawingToolbarState.hideAllDrawings}
          onClick={() => setHideAllDrawings(!drawingToolbarState.hideAllDrawings)}
          testId="drawing-mode-hide-all"
        />
        <ModeToggleButton
          label="Remove All Drawings"
          icon={<RemoveAllIcon />}
          isActive={false}
          onClick={() => removeAllDrawings()}
          testId="drawing-mode-remove-all"
        />
      </div>

      <DrawingToolbarSeparator />

      {/* Object tree access */}
      <div className="drawing-toolbar__utilities">
        <ModeToggleButton
          label="Object Tree"
          icon={<ObjectTreeIcon />}
          isActive={false}
          onClick={() => setRightSidebarPanel('object_tree')}
          testId="drawing-utility-object-tree"
        />
      </div>
    </div>
  );
}

