  .map((ct) => ct.id);

/** Chart types rendered as placeholder UI */
export const PLACEHOLDER_CHART_TYPES: readonly ChartType[] = CHART_TYPE_REGISTRY
  .filter((ct) => ct.status === 'placeholder')
  .map((ct) => ct.id);

/** Chart types gated behind paid boundary */
export const PAID_CHART_TYPES: readonly ChartType[] = CHART_TYPE_REGISTRY
  .filter((ct) => ct.status === 'premium')
  .map((ct) => ct.id);

/** Lookup a chart type descriptor by its id */
export function getChartTypeDescriptor(id: ChartType): ChartTypeDescriptor | undefined {
  return CHART_TYPE_REGISTRY.find((ct) => ct.id === id);
}

/** Get chart types grouped by menu group, preserving sortOrder */
export function getChartTypesByMenuGroup(): Record<ChartTypeMenuGroup, ChartTypeDescriptor[]> {
  const groups: Record<ChartTypeMenuGroup, ChartTypeDescriptor[]> = {
    standard: [],
    line: [],
    area: [],
    special: [],
  };
  for (const ct of CHART_TYPE_REGISTRY) {
    groups[ct.menuGroup]!.push(ct as ChartTypeDescriptor);
  }
  return groups;
}

