}

/** Single plot series within a multi-series indicator (e.g. MACD signal, BB upper/lower) */
export interface IndicatorPlot {
  name: string;
  values: IndicatorResultPoint[];
  style?: 'line' | 'histogram' | 'area' | 'dots' | 'step';
  /** 16è¿å¶ / rgba color string override for this plot series */
  color?: string;
  /** Line width (default 1) */
  lineWidth?: number;
  /** Line style pattern */
  lineStyle?: 'solid' | 'dashed' | 'dotted';
  /** Fill region between two named series */
  fillBetween?: { upper: string; lower: string; color: string };
  /** Fill region above this series to the referenced plot name */
  fillAbove?: string;
  /** Fill region below this series to the referenced plot name */
  fillBelow?: string;
  /** Force into independent sub-pane even when paneType=overlay */
  subPane?: boolean;
  /** Baseline value for histogram plots (e.g. MACD histogram zero line) */
  histogramBaseline?: number;
}

