/**
 * ChartWorkspaceShell â 7-region CSS grid layout for the chart workstation.
 *
 * Region layout (CSS Grid named areas):
 *   Desktop:
 *     "header  header  header"
 *     "toolbar toolbar sidebar"
 *     "toolbar chart   sidebar"
 *     "toolbar bottom  bottom"
 *
 *   Medium:
 *     Same as desktop but narrower sidebar (200px)
 *
 *   Narrow:
 *     "header  header"
 *     "toolbar toolbar"
 *     "left    chart"
 *     (sidebar and bottom become overlay drawers)
 *
 * The overlay-host sits outside the grid as a fixed-position portal.
 * Consumer goals place their components into the named region slots.
 */

import { type ReactNode, useCallback } from 'react';
import { useBreakpoint } from '@features/chart/hooks/useBreakpoint';
import { CHART_TEST_IDS } from '@features/chart/utils/test-ids';

interface ChartWorkspaceShellProps {
  /** Global header â brand, menus, user actions. Pass null when ChartShell provides MinimalGlobalHeader. */
  globalHeader: ReactNode | null;
  /** Instrument toolbar â symbol, timeframe, chart type, indicators */
  instrumentToolbar: ReactNode;
  /** Left vertical drawing toolbar */
  leftDrawingToolbar: ReactNode;
  /** Central chart canvas (dominant region) */
  chartCanvas: ReactNode;
  /** Right sidebar â watchlist, details, alerts, etc. */
  rightSidebar: ReactNode;
  /** Bottom panel â Pine Editor, strategy tester, etc. */
  bottomPanel: ReactNode;
  /** Overlay host â dialogs, menus, toasts, boundaries */
  overlayHost: ReactNode;
  /** Whether the sidebar drawer is open (narrow breakpoint only) */
  sidebarDrawerOpen: boolean;
  /** Whether the bottom panel drawer is open (narrow breakpoint only) */
  bottomDrawerOpen: boolean;
  /** Toggle the sidebar drawer */
  onToggleSidebarDrawer: () => void;
  /** Toggle the bottom panel drawer */
  onToggleBottomDrawer: () => void;
}

/** Sidebar toggle icon (list icon) */
function SidebarToggleIcon() {
  return (
