// âââ Bars Query Memoization âââââââââââââââââââââââââââââââââââââââââââââââââ
//
// Cache bars queries within a short TTL (5 seconds) so that multiple
// indicator calculations for the same symbol+timeframe within a single
// batch or rapid sequence reuse the same bar data without redundant DB
// lookups. The cache is process-level and self-evicting.

interface BarsCacheEntry {
  bars: OhlcvBar[];
  timestamp: number;
}

const barsCache = new Map<string, BarsCacheEntry>();
const BARS_CACHE_TTL_MS = 5_000; // 5 seconds â covers rapid sequential requests

function getBarsCacheKey(symbol: string, timeframe: string, from?: number, to?: number): string {
  return `${symbol}:${timeframe}:${from ?? ''}:${to ?? ''}`;
}

function getCachedBars(symbol: string, timeframe: string, from: number | undefined, to: number | undefined): OhlcvBar[] | null {
  const key = getBarsCacheKey(symbol, timeframe, from, to);
  const entry = barsCache.get(key);
  if (entry && (Date.now() - entry.timestamp) < BARS_CACHE_TTL_MS) {
    return entry.bars;
  }
  if (entry) {
    barsCache.delete(key); // Evict stale entry
  }
  return null;
}

function setCachedBars(symbol: string, timeframe: string, from: number | undefined, to: number | undefined, bars: OhlcvBar[]): void {
  const key = getBarsCacheKey(symbol, timeframe, from, to);
  barsCache.set(key, { bars, timestamp: Date.now() });
  // Evict stale entries when cache grows beyond 100 keys
  if (barsCache.size > 100) {
    const now = Date.now();
    for (const [k, v] of barsCache) {
      if (now - v.timestamp >= BARS_CACHE_TTL_MS) {
        barsCache.delete(k);
      }
    }
  }
}

