/**
 * POST /api/chart/indicators/calculate
 * Calculate indicator values for a symbol and timeframe.
 *
 * Request body: { symbol, timeframe, indicatorKey, parameters, from?, to? }
 * Returns: { indicatorKey, parameters, values: [{timestamp, value}], paneType, isOverlay }
 *
 * Error codes:
 *   400 â INVALID_INDICATOR (unknown indicator key)
 *   400 â INVALID_PARAMETERS (missing required fields)
 *   403 â PAID_INDICATOR (premium indicator)
 *   501 â UNSUPPORTED_INDICATOR (exists but not implemented)
 */
chartRouter.post('/indicators/calculate', (req: Request, res: Response) => {
  try {
    const { symbol, timeframe, indicatorKey, parameters, from, to } = req.body as Partial<CalculateRequest>;

    // Validate required fields
    if (!symbol || typeof symbol !== 'string') {
      res.status(400).json(apiError('MISSING_PARAM', 'Missing required field "symbol"'));
      return;
    }
    if (!timeframe || typeof timeframe !== 'string') {
      res.status(400).json(apiError('MISSING_PARAM', 'Missing required field "timeframe"'));
      return;
    }
    if (!indicatorKey || typeof indicatorKey !== 'string') {
      res.status(400).json(apiError('MISSING_PARAM', 'Missing required field "indicatorKey"'));
      return;
    }

    // Fetch bars for the symbol + timeframe â memoized within TTL
    let bars = getCachedBars(symbol, timeframe, from, to);
    if (!bars) {
      const rawBars = getBars(symbol, timeframe, from, to);
      bars = rawBars.map((b) => ({
        timestamp: b.timestamp,
        open: Number(b.open),
        high: Number(b.high),
        low: Number(b.low),
        close: Number(b.close),
        volume: b.volume,
      }));
      setCachedBars(symbol, timeframe, from, to, bars);
    }

    const request: CalculateRequest = {
      symbol,
      timeframe,
      indicatorKey,
      parameters: parameters ?? {},
      from,
      to,
    };

    const result = calculateIndicator(request, bars);

    if (isCalculateError(result)) {
      // Map error codes to HTTP status
      const statusMap: Record<string, number> = {
        INVALID_INDICATOR: 400,
        INVALID_PARAMETERS: 400,
        NO_DATA: 404,
        PAID_INDICATOR: 403,
        UNSUPPORTED_INDICATOR: 501,
      };
      const status = statusMap[result.code] ?? 400;
      const boundary = result.code === 'PAID_INDICATOR' ? 'paid' as const : undefined;
      res.status(status).json(apiError(result.code, result.error, boundary));
      return;
    }

    res.json(apiSuccess(result));
  } catch (err) {
    console.error('Error in POST /api/chart/indicators/calculate:', err);
    res.status(500).json(apiError('INTERNAL_ERROR', 'Internal server error'));
  }
});

