import Database from 'better-sqlite3';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import * as schema from './schema.js';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DEFAULT_DB_PATH = path.resolve(__dirname, '../../screener.db');

let _db: ReturnType<typeof drizzle> | null = null;
let _sqlite: Database.Database | null = null;

/**
 * Create or return a singleton Drizzle ORM instance backed by better-sqlite3.
 * Uses the project-root screener.db by default; override with DB_PATH env var.
 */
export function getDb(dbPath?: string): ReturnType<typeof drizzle> {
  if (_db) return _db;

  const resolvedPath = dbPath ?? process.env.DB_PATH ?? DEFAULT_DB_PATH;
  _sqlite = new Database(resolvedPath);

  // Enable WAL mode for better concurrent read performance
