/**
 * Chart service â Drizzle ORM query functions for the chart module.
 * All database access for chart endpoints goes through this service layer.
 * Uses the Drizzle ORM sync API with .all() / .get() for better-sqlite3.
 */

import { eq, and, like, gte, lte, asc, or } from 'drizzle-orm';
import { getDb } from '../db/connection.js';
import {
  instruments,
  market_bars,
  quotes,
  indicator_definitions,
  chart_layouts,
  drawing_objects,
  watchlists,
  alerts,
  chart_settings,
  templates,
} from '../db/schema.js';
import type {
  Instrument,
  MarketBar,
  Quote,
  IndicatorDefinition,
  ChartLayout,
  DrawingObject,
  Watchlist,
  Alert,
  ChartSetting,
  Template,
} from '../db/schema.js';

// âââ Symbol Search ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getInstrument(symbol: string): Instrument | null {
  const db = getDb();
  return db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get() ?? null;
}

export function searchSymbols(query: string): Instrument[] {
  const db = getDb();
  const term = `%${query}%`;
  return db
    .select()
    .from(instruments)
    .where(or(
      like(instruments.symbol, term),
      like(instruments.companyName, term),
      like(instruments.sector, term),
    ))
    .limit(20)
    .all();
}

// âââ Bars âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getBars(
  symbol: string,
  timeframe: string,
  from?: number,
  to?: number
): (MarketBar & { symbol: string })[] {
  const db = getDb();

  // Resolve instrument ID from symbol
  const instrument = db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get();

  if (!instrument) return [];

  // Build conditions
  const conditions = [eq(market_bars.instrumentId, instrument.id), eq(market_bars.timeframe, timeframe)];
  if (from !== undefined) conditions.push(gte(market_bars.timestamp, from));
  if (to !== undefined) conditions.push(lte(market_bars.timestamp, to));

  const bars = db
    .select()
    .from(market_bars)
    .where(and(...conditions))
    .orderBy(asc(market_bars.timestamp))
    .all();

  // Attach symbol for client convenience
  return bars.map((bar) => ({ ...bar, symbol }));
}

// âââ Quotes âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getQuote(symbol: string): (Quote & { symbol: string }) | null {
  const db = getDb();

  const instrument = db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get();

  if (!instrument) return null;

  const quote = db
    .select()
    .from(quotes)
    .where(eq(quotes.instrumentId, instrument.id))
    .limit(1)
    .get();

  if (!quote) return null;

  return { ...quote, symbol };
}

// âââ Indicator Definitions ââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getIndicatorDefinitions(): IndicatorDefinition[] {
  const db = getDb();
  return db.select().from(indicator_definitions).all();
}

/**
 * Search indicator definitions by query string.
 * Matches against key and name fields using case-insensitive substring search.
 */
export function searchIndicatorDefinitions(query: string): IndicatorDefinition[] {
  const db = getDb();
  const term = `%${query}%`;
  return db
    .select()
    .from(indicator_definitions)
    .where(or(
      like(indicator_definitions.key, term),
      like(indicator_definitions.name, term),
    ))
    .all();
}

// âââ Watchlists ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getWatchlists(): Watchlist[] {
  const db = getDb();
  return db.select().from(watchlists).all();
}

export function createWatchlist(name: string, symbolsJson: string): Watchlist {
  const db = getDb();
  const result = db.insert(watchlists).values({
    name,
    symbolsJson,
  }).returning().all();
  return result[0]!;
}

export function renameWatchlist(id: string, name: string): Watchlist | null {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return null;

  const result = db
    .update(watchlists)
    .set({ name })
    .where(eq(watchlists.id, idNum))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

export function deleteWatchlist(id: string): boolean {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return false;

  const result = db.delete(watchlists).where(eq(watchlists.id, idNum)).returning().all();
  return result.length > 0;
}

export function addSymbolToWatchlist(watchlistId: string, symbol: string): Watchlist | null {
  const db = getDb();
  const idNum = parseInt(watchlistId, 10);
  if (isNaN(idNum)) return null;

  const list = db.select().from(watchlists).where(eq(watchlists.id, idNum)).limit(1).get();
  if (!list) return null;

  const symbols = JSON.parse(list.symbolsJson) as string[];
  if (symbols.includes(symbol)) return list;

  symbols.push(symbol);
  const result = db
    .update(watchlists)
    .set({ symbolsJson: JSON.stringify(symbols) })
    .where(eq(watchlists.id, idNum))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

export function removeSymbolFromWatchlist(watchlistId: string, symbol: string): Watchlist | null {
  const db = getDb();
  const idNum = parseInt(watchlistId, 10);
  if (isNaN(idNum)) return null;

  const list = db.select().from(watchlists).where(eq(watchlists.id, idNum)).limit(1).get();
  if (!list) return null;

  const symbols = JSON.parse(list.symbolsJson) as string[];
  const updated = symbols.filter((s) => s !== symbol);

  const result = db
    .update(watchlists)
    .set({ symbolsJson: JSON.stringify(updated) })
    .where(eq(watchlists.id, idNum))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

/**
 * Enrich a watchlist's string-based symbols array with quote data.
 * Converts ["NASDAQ:NVDA", ...] â [{ symbol: "NVDA", exchange: "NASDAQ", lastPrice, change, changePercent, companyName }, ...]
 */
export function enrichWatchlistSymbols(
  symbolsJson: string,
): Array<{
  symbol: string;
  exchange: string;
  companyName: string;
  lastPrice: number;
  change: number;
  changePercent: number;
}> {
  const db = getDb();
  const rawSymbols = JSON.parse(symbolsJson) as string[];

  return rawSymbols.map((fullSymbol) => {
    const colonIdx = fullSymbol.indexOf(':');
    const exchange = colonIdx > 0 ? fullSymbol.slice(0, colonIdx) : '';
    const ticker = colonIdx > 0 ? fullSymbol.slice(colonIdx + 1) : fullSymbol;

    // Look up instrument and quote
    const instrument = db
      .select()
      .from(instruments)
      .where(eq(instruments.symbol, fullSymbol))
      .limit(1)
      .get();

    let lastPrice = 0;
    let change = 0;
    let changePercent = 0;
    let companyName = ticker;

    if (instrument) {
      companyName = instrument.companyName ?? ticker;
      const quote = db
        .select()
        .from(quotes)
        .where(eq(quotes.instrumentId, instrument.id))
        .limit(1)
        .get();
      if (quote) {
        lastPrice = Number(quote.lastPrice);
        change = Number(quote.change);
        changePercent = Number(quote.changePercent);
      }
    }

    return { symbol: ticker, exchange, companyName, lastPrice, change, changePercent };
  });
}

// âââ Drawings ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getDrawings(layoutId: string): DrawingObject[] {
  const db = getDb();
  const layoutIdNum = parseInt(layoutId, 10);
  if (isNaN(layoutIdNum)) return [];

  return db
    .select()
    .from(drawing_objects)
    .where(eq(drawing_objects.layoutId, layoutIdNum))
    .all();
}

export function createDrawing(
  layoutId: string,
  data: { toolType: string; pointsJson: string; styleJson?: string; text?: string; locked?: boolean; visible?: boolean }
): DrawingObject {
  const db = getDb();
  const layoutIdNum = parseInt(layoutId, 10);
  if (isNaN(layoutIdNum)) throw new Error('Invalid layoutId');

  const result = db.insert(drawing_objects).values({
    layoutId: layoutIdNum,
    toolType: data.toolType,
    pointsJson: data.pointsJson,
    styleJson: data.styleJson ?? null,
    text: data.text ?? null,
    locked: data.locked ?? false,
    visible: data.visible ?? true,
  }).returning().all();

  return result[0]!;
}

export function updateDrawing(
  id: string,
  data: Partial<{ toolType: string; pointsJson: string; styleJson: string; text: string; locked: boolean; visible: boolean }>
): DrawingObject | null {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return null;

  const result = db
    .update(drawing_objects)
    .set(data)
    .where(eq(drawing_objects.id, idNum))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

export function deleteDrawing(id: string): boolean {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return false;

  const result = db.delete(drawing_objects).where(eq(drawing_objects.id, idNum)).returning().all();
  return result.length > 0;
}

// âââ Alerts ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getAlerts(_symbol?: string): Alert[] {
  const db = getDb();
  // Alerts table doesn't have a symbol column directly;
  // conditionJson may contain symbol info. For simplicity, return all alerts.
  return db.select().from(alerts).all();
}

export function createAlert(data: {
  conditionJson: string;
  message?: string;
  isActive?: boolean;
  isAuthGated?: boolean;
  operator?: string;
  threshold?: string;
  targetSymbol?: string;
  targetSource?: string;
  expiration?: string;
  frequency?: string;
  actionsJson?: string;
}): Alert {
  const db = getDb();
  const result = db.insert(alerts).values({
    conditionJson: data.conditionJson,
    message: data.message ?? null,
    isActive: data.isActive ?? true,
    isAuthGated: data.isAuthGated ?? false,
    operator: data.operator ?? null,
    threshold: data.threshold ?? null,
    targetSymbol: data.targetSymbol ?? null,
    targetSource: data.targetSource ?? null,
    expiration: data.expiration ?? null,
    frequency: data.frequency ?? null,
    actionsJson: data.actionsJson ?? null,
  }).returning().all();

  return result[0]!;
}

export function deleteAlert(id: string): boolean {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return false;

  const result = db.delete(alerts).where(eq(alerts.id, idNum)).returning().all();
  return result.length > 0;
}

export function updateAlert(
  id: string,
  data: Partial<{ conditionJson: string; message: string; isActive: boolean; operator: string; threshold: string; targetSymbol: string; targetSource: string; expiration: string; frequency: string; actionsJson: string }>,
): Alert | null {
  const db = getDb();
  const idNum = parseInt(id, 10);
  if (isNaN(idNum)) return null;

  const result = db
    .update(alerts)
    .set(data)
    .where(eq(alerts.id, idNum))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

/** Get alert history â returns mock data for the local replica */
export function getAlertHistory(_symbol?: string): Array<{
  id: number;
  alertId: number;
  triggeredAt: number;
  conditionJson: string;
  message: string | null;
  status: string;
}> {
  // Return synthetic history based on existing alerts
  const db = getDb();
  const allAlerts = db.select().from(alerts).all();

  return allAlerts
    .filter((a) => !Boolean(a.isActive))
    .slice(0, 20)
    .map((a, i) => ({
      id: 1000 + i,
      alertId: a.id,
      triggeredAt: Date.now() - (i + 1) * 3600000,
      conditionJson: a.conditionJson,
      message: a.message,
      status: 'triggered' as string,
    }));
}

