export function getChartSettings(_layoutId: string): ChartSetting | null {
  const db = getDb();
  // Chart settings is a single-row table; layoutId is ignored for now
  // but the parameter is kept for API consistency and future per-layout settings.
  return db.select().from(chart_settings).limit(1).get() ?? null;
}

export function updateChartSettings(
  _layoutId: string,
  data: Partial<{
    theme: string;
    timezone: string;
    scaleMode: string;
    showGrid: boolean;
    showCrosshair: boolean;
    showVolume: boolean;
    candleStyleJson: string;
  }>
): ChartSetting | null {
  const db = getDb();
  // Update the first row (single-row table pattern)
  const existing = db.select().from(chart_settings).limit(1).get();
  if (!existing) {
    // Insert if no row exists
    const result = db.insert(chart_settings).values({
      theme: data.theme ?? 'dark',
      timezone: data.timezone ?? 'Etc/UTC',
      scaleMode: data.scaleMode ?? 'normal',
      showGrid: data.showGrid ?? true,
      showCrosshair: data.showCrosshair ?? true,
      showVolume: data.showVolume ?? true,
      candleStyleJson: data.candleStyleJson ?? null,
    }).returning().all();
    return result[0]!;
  }

  const result = db
    .update(chart_settings)
    .set(data)
    .where(eq(chart_settings.id, existing.id))
    .returning()
    .all();

  return result.length > 0 ? result[0]! : null;
}

