export interface ChartLayoutAccessStatus {
  layoutId: string;
  status: 'accessible' | 'restricted' | 'not_shareable' | 'not_found';
  message?: string;
}

export function getChartLayoutAccess(layoutId: string): ChartLayoutAccessStatus {
  const db = getDb();
  const idNum = parseInt(layoutId, 10);

  // If the layoutId is not a numeric ID, treat it as a share link that is restricted
  // (TradingView chart URLs use alphanumeric IDs like 'fY7jJ0Bi')
  if (isNaN(idNum)) {
    return {
      layoutId,
      status: 'restricted',
      message: 'This chart layout is private and cannot be accessed.',
    };
  }

  const layout = db.select().from(chart_layouts).where(eq(chart_layouts.id, idNum)).limit(1).get();
  if (!layout) {
    return {
      layoutId,
      status: 'not_found',
      message: 'This chart layout does not exist.',
    };
  }

  return {
    layoutId,
    status: 'accessible',
  };
}

