} from '../db/schema.js';

// âââ Symbol Search ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getInstrument(symbol: string): Instrument | null {
  const db = getDb();
  return db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get() ?? null;
}

export function searchSymbols(query: string): Instrument[] {
  const db = getDb();
  const term = `%${query}%`;
  return db
    .select()
    .from(instruments)
    .where(or(
      like(instruments.symbol, term),
      like(instruments.companyName, term),
      like(instruments.sector, term),
    ))
    .limit(20)
    .all();
}

// âââ Bars âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getBars(
  symbol: string,
  timeframe: string,
  from?: number,
  to?: number
): (MarketBar & { symbol: string })[] {
  const db = getDb();

  // Resolve instrument ID from symbol
  const instrument = db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get();

  if (!instrument) return [];

  // Build conditions
  const conditions = [eq(market_bars.instrumentId, instrument.id), eq(market_bars.timeframe, timeframe)];
  if (from !== undefined) conditions.push(gte(market_bars.timestamp, from));
  if (to !== undefined) conditions.push(lte(market_bars.timestamp, to));

  const bars = db
    .select()
    .from(market_bars)
    .where(and(...conditions))
    .orderBy(asc(market_bars.timestamp))
    .all();

  // Attach symbol for client convenience
  return bars.map((bar) => ({ ...bar, symbol }));
}

// âââ Quotes âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function getQuote(symbol: string): (Quote & { symbol: string }) | null {
  const db = getDb();

  const instrument = db
    .select()
    .from(instruments)
    .where(eq(instruments.symbol, symbol))
    .limit(1)
    .get();

  if (!instrument) return null;

  const quote = db
    .select()
    .from(quotes)
    .where(eq(quotes.instrumentId, instrument.id))
    .limit(1)
    .get();

  if (!quote) return null;

  return { ...quote, symbol };
}

