function mapWatchlists(raw: ServerWatchlistsResponse): Watchlist[] {
  return raw.watchlists.map((w) => ({
    id: String(w.id),
    name: w.name,
    // Prefer the server-enriched `symbols` array; fall back to parsing symbolsJson
    symbols: w.symbols
      ? w.symbols.map((s) => ({
          symbol: s.symbol,
          exchange: s.exchange,
          companyName: s.companyName,
          lastPrice: s.lastPrice,
          change: s.change,
          changePercent: s.changePercent,
        }))
      : (JSON.parse(w.symbolsJson) as Watchlist['symbols']),
