  async updateTemplate(id: string, data: {
    name?: string;
    payload?: Record<string, unknown>;
    isAuthGated?: boolean;
  }): Promise<TemplateEntry> {
    const body: Record<string, unknown> = {};
    if (data.name !== undefined) body.name = data.name;
    if (data.payload !== undefined) body.payloadJson = JSON.stringify(data.payload);
    if (data.isAuthGated !== undefined) body.isAuthGated = data.isAuthGated;
