/**
 * Chart module database seeding.
 *
 * Creates all chart tables, generates deterministic synthetic data via
 * generate-chart-data.ts, and inserts into the SQLite database.
 * This module is called from the main seed/index.ts entry point.
 */

import type Database from 'better-sqlite3';
import { generateChartData, type ChartSeedData } from './generate-chart-data.js';

/**
 * Drop and recreate all chart module tables.
 */
export function createChartTables(sqlite: Database.Database): void {
  // Drop in dependency order (children first)
  sqlite.exec(`
    DROP TABLE IF EXISTS alert_history;
    DROP TABLE IF EXISTS templates;
    DROP TABLE IF EXISTS chart_settings;
    DROP TABLE IF EXISTS alerts;
    DROP TABLE IF EXISTS watchlists;
    DROP TABLE IF EXISTS drawing_objects;
    DROP TABLE IF EXISTS chart_layouts;
    DROP TABLE IF EXISTS indicator_definitions;
    DROP TABLE IF EXISTS quotes;
    DROP TABLE IF EXISTS market_bars;
    DROP TABLE IF EXISTS instruments;
  `);

  // Create tables
  sqlite.exec(`
    CREATE TABLE instruments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      symbol TEXT NOT NULL UNIQUE,
      exchange TEXT NOT NULL,
      market TEXT NOT NULL,
      asset_class TEXT NOT NULL,
      company_name TEXT NOT NULL,
      sector TEXT,
      industry TEXT,
      timezone TEXT NOT NULL DEFAULT 'Etc/UTC',
      session TEXT NOT NULL
    );

    CREATE TABLE market_bars (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      instrument_id INTEGER NOT NULL REFERENCES instruments(id),
      timeframe TEXT NOT NULL,
      timestamp INTEGER NOT NULL,
      open TEXT NOT NULL,
      high TEXT NOT NULL,
      low TEXT NOT NULL,
      close TEXT NOT NULL,
      volume INTEGER NOT NULL DEFAULT 0
    );

    CREATE TABLE quotes (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      instrument_id INTEGER NOT NULL UNIQUE REFERENCES instruments(id),
      last_price TEXT NOT NULL,
      change TEXT NOT NULL,
      change_percent TEXT NOT NULL,
      market_status TEXT NOT NULL DEFAULT 'closed'
    );

    CREATE TABLE indicator_definitions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      key TEXT NOT NULL UNIQUE,
      name TEXT NOT NULL,
      category TEXT NOT NULL,
      inputs_schema TEXT NOT NULL,
      default_inputs TEXT NOT NULL,
      pane_type TEXT NOT NULL,
      is_overlay INTEGER NOT NULL DEFAULT 0,
      is_paid INTEGER NOT NULL DEFAULT 0
    );

    CREATE TABLE chart_layouts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      symbol TEXT NOT NULL,
      timeframe TEXT NOT NULL DEFAULT '1D',
      chart_type TEXT NOT NULL DEFAULT 'candles',
      visible_range_json TEXT,
      indicators_json TEXT,
      drawings_json TEXT,
      panes_json TEXT,
      settings_json TEXT,
      layout_name TEXT,
      grid_preset TEXT,
      chart_instances_json TEXT,
      active_chart_id TEXT,
      sync_settings_json TEXT,
      is_default INTEGER NOT NULL DEFAULT 0,
      global_workspace_ui_state_json TEXT
    );

    CREATE TABLE drawing_objects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      layout_id INTEGER NOT NULL REFERENCES chart_layouts(id),
      tool_type TEXT NOT NULL,
      points_json TEXT NOT NULL,
      style_json TEXT,
      text TEXT,
      locked INTEGER NOT NULL DEFAULT 0,
      visible INTEGER NOT NULL DEFAULT 1
    );

    CREATE TABLE watchlists (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      symbols_json TEXT NOT NULL
    );

    CREATE TABLE alerts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      condition_json TEXT NOT NULL,
      message TEXT,
      is_active INTEGER NOT NULL DEFAULT 1,
      is_auth_gated INTEGER NOT NULL DEFAULT 0,
      operator TEXT,
      threshold TEXT,
      target_symbol TEXT,
      target_source TEXT,
      expiration TEXT,
      frequency TEXT,
      actions_json TEXT,
      created_at INTEGER,
      last_triggered_at INTEGER
    );

    CREATE TABLE alert_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      alert_id INTEGER NOT NULL REFERENCES alerts(id),
      triggered_at INTEGER NOT NULL,
      condition_json TEXT NOT NULL,
      message TEXT,
      status TEXT NOT NULL DEFAULT 'triggered'
    );

    CREATE TABLE chart_settings (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      theme TEXT NOT NULL DEFAULT 'dark',
      timezone TEXT NOT NULL DEFAULT 'Etc/UTC',
      scale_mode TEXT NOT NULL DEFAULT 'normal',
      show_grid INTEGER NOT NULL DEFAULT 1,
      show_crosshair INTEGER NOT NULL DEFAULT 1,
      show_volume INTEGER NOT NULL DEFAULT 1,
      candle_style_json TEXT
    );

    CREATE TABLE templates (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      family TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      is_built_in INTEGER NOT NULL DEFAULT 0,
      is_auth_gated INTEGER NOT NULL DEFAULT 0,
      updated_at INTEGER
    );
  `);

  // Create indexes for chart table query performance
  sqlite.exec(`
    CREATE INDEX idx_instruments_symbol ON instruments(symbol);
    CREATE INDEX idx_instruments_exchange ON instruments(exchange);
    CREATE INDEX idx_instruments_asset_class ON instruments(asset_class);
    CREATE INDEX idx_instruments_market ON instruments(market);
    CREATE INDEX idx_market_bars_instrument_timeframe ON market_bars(instrument_id, timeframe);
    CREATE INDEX idx_market_bars_instrument_timeframe_timestamp ON market_bars(instrument_id, timeframe, timestamp);
    CREATE INDEX idx_quotes_instrument ON quotes(instrument_id);
    CREATE INDEX idx_indicator_definitions_key ON indicator_definitions(key);
    CREATE INDEX idx_indicator_definitions_category ON indicator_definitions(category);
    CREATE INDEX idx_drawing_objects_layout ON drawing_objects(layout_id);
  `);
}

/**
 * Seed all chart module data into the database.
 *
 * @param sqlite - Connected better-sqlite3 database instance
 * @returns Summary statistics of seeded data
 */
export function seedChartData(sqlite: Database.Database): {
  instrumentsCount: number;
  barsCount: number;
  quotesCount: number;
  indicatorDefsCount: number;
  watchlistsCount: number;
  chartLayoutsCount: number;
  chartSettingsCount: number;
} {
  // Step 1: Create tables
  createChartTables(sqlite);

  // Step 2: Generate all data
  const data: ChartSeedData = generateChartData();

  // Step 3: Insert instruments
  const insertInstrument = sqlite.prepare(`
    INSERT INTO instruments (symbol, exchange, market, asset_class, company_name, sector, industry, timezone, session)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const insertInstruments = sqlite.transaction((items: ChartSeedData['instruments']) => {
    for (const inst of items) {
      insertInstrument.run(
        inst.symbol, inst.exchange, inst.market, inst.assetClass,
        inst.companyName, inst.sector, inst.industry, inst.timezone, inst.session,
      );
    }
  });

  insertInstruments(data.instruments);
  console.log(`  Inserted ${data.instruments.length} instruments`);

  // Step 4: Insert market bars (batched for performance)
  const insertBar = sqlite.prepare(`
    INSERT INTO market_bars (instrument_id, timeframe, timestamp, open, high, low, close, volume)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const BATCH_SIZE = 5000;
  let barsInserted = 0;

  const insertBarsBatch = sqlite.transaction((bars: ChartSeedData['bars']) => {
    for (const bar of bars) {
      insertBar.run(
        bar.instrumentId, bar.timeframe, bar.timestamp,
        bar.open, bar.high, bar.low, bar.close, bar.volume,
      );
      barsInserted++;
    }
  });

  // Insert bars in batches to avoid transaction lock timeout
  for (let i = 0; i < data.bars.length; i += BATCH_SIZE) {
    const batch = data.bars.slice(i, i + BATCH_SIZE);
    insertBarsBatch(batch);
  }
  console.log(`  Inserted ${barsInserted} market bars`);

  // Step 5: Insert quotes
  const insertQuote = sqlite.prepare(`
    INSERT INTO quotes (instrument_id, last_price, change, change_percent, market_status)
    VALUES (?, ?, ?, ?, ?)
  `);

  const insertQuotes = sqlite.transaction((items: ChartSeedData['quotes']) => {
    for (const q of items) {
      insertQuote.run(q.instrumentId, q.lastPrice, q.change, q.changePercent, q.marketStatus);
    }
  });

  insertQuotes(data.quotes);
  console.log(`  Inserted ${data.quotes.length} quotes`);

  // Step 6: Insert indicator definitions
  const insertIndicator = sqlite.prepare(`
    INSERT INTO indicator_definitions (key, name, category, inputs_schema, default_inputs, pane_type, is_overlay, is_paid)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `);

  const insertIndicators = sqlite.transaction((items: ChartSeedData['indicatorDefinitions']) => {
    for (const ind of items) {
      insertIndicator.run(
        ind.key, ind.name, ind.category, ind.inputsSchema,
        ind.defaultInputs, ind.paneType, ind.isOverlay ? 1 : 0, ind.isPaid ? 1 : 0,
      );
    }
  });

  insertIndicators(data.indicatorDefinitions);
  console.log(`  Inserted ${data.indicatorDefinitions.length} indicator definitions`);

  // Step 7: Insert default watchlist
  const insertWatchlist = sqlite.prepare(`
    INSERT INTO watchlists (name, symbols_json)
    VALUES (?, ?)
  `);

  insertWatchlist.run('Default', JSON.stringify(data.defaultWatchlistSymbols));
  console.log(`  Inserted 1 default watchlist`);

  // Step 8: Insert default chart layout
  const insertLayout = sqlite.prepare(`
    INSERT INTO chart_layouts (symbol, timeframe, chart_type, visible_range_json, indicators_json, drawings_json, panes_json, settings_json)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `);

  insertLayout.run(
    'NASDAQ:NVDA',
    '1D',
    'candles',
    null,
    JSON.stringify([]),
    JSON.stringify([]),
    JSON.stringify([{ id: 'main', type: 'main', height: 80 }]),
    JSON.stringify({
      theme: 'dark',
      timezone: 'Etc/UTC',
      scaleMode: 'normal',
      showGrid: true,
      showCrosshair: true,
      showVolume: true,
      candleStyle: {
        upColor: '#26a69a',
        downColor: '#ef5350',
        upWickColor: '#26a69a',
        downWickColor: '#ef5350',
        upBorderVisible: false,
        downBorderVisible: false,
      },
    }),
  );

  // Additional built-in layouts for the layout selector
  const defaultSettings = JSON.stringify({
    theme: 'dark',
    timezone: 'Etc/UTC',
    scaleMode: 'normal',
    showGrid: true,
    showCrosshair: true,
    showVolume: true,
    candleStyle: {
      upColor: '#26a69a',
      downColor: '#ef5350',
      upWickColor: '#26a69a',
      downWickColor: '#ef5350',
      upBorderVisible: false,
      downBorderVisible: false,
    },
  });

  insertLayout.run(
    'NASDAQ:AAPL', '1D', 'candles', null,
    JSON.stringify([{ id: 'sma-20', key: 'SMA', name: 'Simple Moving Average', parameters: { length: 20 }, values: [], paneType: 'overlay', isOverlay: true }]),
    JSON.stringify([]),
    JSON.stringify([{ id: 'main', type: 'main', height: 80 }]),
    defaultSettings,
  );

  insertLayout.run(
    'NASDAQ:MSFT', '1h', 'line', null,
    JSON.stringify([]),
    JSON.stringify([]),
    JSON.stringify([{ id: 'main', type: 'main', height: 80 }]),
    defaultSettings,
  );

  insertLayout.run(
    'NASDAQ:TSLA', '1D', 'area', null,
    JSON.stringify([{ id: 'ema-9', key: 'EMA', name: 'Exponential Moving Average', parameters: { length: 9 }, values: [], paneType: 'overlay', isOverlay: true }]),
    JSON.stringify([]),
    JSON.stringify([{ id: 'main', type: 'main', height: 80 }]),
    defaultSettings,
  );

  console.log(`  Inserted 4 built-in chart layouts`);

  // Step 9: Insert default chart settings
  const insertSettings = sqlite.prepare(`
    INSERT INTO chart_settings (theme, timezone, scale_mode, show_grid, show_crosshair, show_volume, candle_style_json)
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `);

  insertSettings.run(
    'dark',
    'Etc/UTC',
    'normal',
    1, 1, 1,
    JSON.stringify({
      upColor: '#26a69a',
      downColor: '#ef5350',
      upWickColor: '#26a69a',
      downWickColor: '#ef5350',
      upBorderVisible: false,
      downBorderVisible: false,
    }),
  );
  console.log(`  Inserted 1 chart settings row`);

  // Return counts for verification
  const instrumentsCount = sqlite.prepare('SELECT COUNT(*) as c FROM instruments').get() as { c: number };
  const barsCount = sqlite.prepare('SELECT COUNT(*) as c FROM market_bars').get() as { c: number };
  const quotesCount = sqlite.prepare('SELECT COUNT(*) as c FROM quotes').get() as { c: number };
  const indicatorDefsCount = sqlite.prepare('SELECT COUNT(*) as c FROM indicator_definitions').get() as { c: number };
  const watchlistsCount = sqlite.prepare('SELECT COUNT(*) as c FROM watchlists').get() as { c: number };
  const chartLayoutsCount = sqlite.prepare('SELECT COUNT(*) as c FROM chart_layouts').get() as { c: number };
  const chartSettingsCount = sqlite.prepare('SELECT COUNT(*) as c FROM chart_settings').get() as { c: number };

  return {
    instrumentsCount: instrumentsCount.c,
    barsCount: barsCount.c,
    quotesCount: quotesCount.c,
    indicatorDefsCount: indicatorDefsCount.c,
    watchlistsCount: watchlistsCount.c,
    chartLayoutsCount: chartLayoutsCount.c,
    chartSettingsCount: chartSettingsCount.c,
  };
}

