/**
 * Parabolic SAR (Stop and Reverse) calculation.
 *
 * Wilder 1978 state-machine algorithm.
 * Output style: 'dots' â each point is a SAR value.
 *
 * Formula:
 *   state: trend â {long, short}, EP (extreme point), AF (accel factor)
 *   init: detect first trend from bars[1] vs bars[0]
 *   if long:
 *     SAR[t] = SAR[t-1] + AF * (EP â SAR[t-1])
 *     SAR[t] = min(SAR[t], L[t-1], L[t-2])   // SAR can't enter prior bar range
 *     if H[t] > EP: EP = H[t]; AF = min(AF + step, maxStep)
 *     if L[t] < SAR[t]: flip to short; SAR = EP; EP = L[t]; AF = step
 *   if short:
 *     SAR[t] = SAR[t-1] + AF * (EP â SAR[t-1])
 *     SAR[t] = max(SAR[t], H[t-1], H[t-2])
 *     if L[t] < EP: EP = L[t]; AF = min(AF + step, maxStep)
 *     if H[t] > SAR[t]: flip to long; SAR = EP; EP = H[t]; AF = step
 */

import type { OhlcvBar, IndicatorPoint, IndicatorPlot, CalculatorResult } from '../types.js';

export interface ParabolicSarParameters {
  /** Acceleration factor step (default: 0.02) */
  step: number;
  /** Maximum acceleration factor (default: 0.2) */
  maxStep: number;
}

export function calculateParabolicSar(bars: OhlcvBar[], params: ParabolicSarParameters): CalculatorResult {
  const step = Math.max(0.001, params.step ?? 0.02);
  const maxStep = Math.max(step, params.maxStep ?? 0.2);

  if (bars.length < 2) return { values: [] };

  const points: IndicatorPoint[] = [];
  let trend: 'long' | 'short';
  let af = step;
  let ep: number;
  let sar: number;

  // Initialize: detect initial trend direction
  if (bars[1]!.close > bars[0]!.close) {
    trend = 'long';
    ep = bars[0]!.high;
    sar = bars[0]!.low; // Start SAR at the low of the first bar
  } else {
    trend = 'short';
    ep = bars[0]!.low;
    sar = bars[0]!.high; // Start SAR at the high of the first bar
  }

  for (let i = 1; i < bars.length; i++) {
    // Calculate new SAR
    sar = sar + af * (ep - sar);

    if (trend === 'long') {
      // SAR cannot enter the previous two bars' range
      if (i >= 2) {
        sar = Math.min(sar, bars[i - 1]!.low, bars[i - 2]!.low);
      } else {
        sar = Math.min(sar, bars[i - 1]!.low);
      }

      // Check for flip
      if (bars[i]!.low < sar) {
        // Flip to short
        trend = 'short';
        sar = ep;
        ep = bars[i]!.low;
        af = step;
      } else {
        // Update EP and AF
        if (bars[i]!.high > ep) {
          ep = bars[i]!.high;
          af = Math.min(af + step, maxStep);
        }
      }
    } else {
      // trend === 'short'
      // SAR cannot enter the previous two bars' range
      if (i >= 2) {
        sar = Math.max(sar, bars[i - 1]!.high, bars[i - 2]!.high);
      } else {
        sar = Math.max(sar, bars[i - 1]!.high);
      }

      // Check for flip
      if (bars[i]!.high > sar) {
        // Flip to long
        trend = 'long';
        sar = ep;
        ep = bars[i]!.high;
        af = step;
      } else {
        // Update EP and AF
        if (bars[i]!.low < ep) {
          ep = bars[i]!.low;
          af = Math.min(af + step, maxStep);
        }
      }
    }

    points.push({
      timestamp: bars[i]!.timestamp,
      value: sar,
    });
  }

  // Return with primaryStyle dots â the primary series IS the SAR dots;
  // no need to duplicate in plots[].
  return { values: points, primaryStyle: 'dots' };
}

