/**
 * Chart API client â typed wrapper around all /api/chart/* endpoints.
 *
 * This module is the sole gateway from frontend to backend for chart domain data.
 * No component should call fetch directly for chart endpoints.
 *
 * Error handling maps HTTP status codes to user-facing messages and structured
 * error objects (ChartApiError). All functions return typed responses matching
 * the server API shapes from @features/chart/types.
 */

import type {
  SymbolSearchResult,
  InstrumentDetails,
  BarsResponse,
  QuoteResponse,
  IndicatorDefinition,
  IndicatorCalculateRequest,
  IndicatorCalculateResponse,
  Watchlist,
  DrawingObject,
  DrawingPoint,
  DrawingStyle,
  DrawingTool,
  AlertItem,
  CreateDrawingRequest,
  UpdateDrawingRequest,
  CreateAlertRequest,
  CreateLayoutRequest,
  ChartLayout,
  LayoutAccessResponse,
  ChartSettings,
  SettingsResponse,
  WorkspaceBootstrapResponse,
  Timeframe,
  ChartType,
  ActiveIndicator,
  PaneConfig,
  TemplateFamily,
  TemplateEntry,
} from '@features/chart/types';

// âââ Error Class âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Structured error for chart API failures.
 * Maps HTTP status codes to user-facing messages and preserves
 * the raw server error payload for debugging.
 */
export class ChartApiError extends Error {
  public readonly status: number;
  public readonly code: string;
  public readonly detail: string;

  constructor(status: number, code: string, detail: string) {
    super(detail);
    this.name = 'ChartApiError';
    this.status = status;
    this.code = code;
    this.detail = detail;
  }
}

// âââ HTTP Status â User-Facing Messages ââââââââââââââââââââââââââââââââââââââââ

const STATUS_MESSAGES: Record<number, string> = {
  400: 'Invalid request. Please check your input and try again.',
  401: 'Sign in is required to perform this action.',
  403: 'You do not have permission to access this resource.',
  404: 'The requested resource was not found.',
  422: 'The data you submitted could not be processed.',
  429: 'Too many requests. Please wait a moment and try again.',
  500: 'An unexpected server error occurred. Please try again later.',
};

function userMessageForStatus(status: number): string {
  return STATUS_MESSAGES[status] ?? `Request failed with status ${status}.`;
}

// âââ Internal fetch helpers ââââââââââââââââââââââââââââââââââââââââââââââââââââ

const API_BASE = '/api/chart';
const REQUEST_TIMEOUT_MS = 15000;

type ApiEnvelope<T> =
  | { ok: true; data: T; meta?: Record<string, unknown> }
  | { ok: false; error: { code: string; message: string; boundary?: 'auth' | 'paid' | 'route' | 'unsupported' } };

// Server may still emit legacy { error: string } / { message: string } shapes on some error paths.
interface LegacyErrorResponse { error?: string; message?: string }

function timeoutSignal(ms: number): AbortSignal {
  const ctrl = new AbortController();
  setTimeout(() => ctrl.abort(new DOMException('Request timed out', 'TimeoutError')), ms);
  return ctrl.signal;
}

async function parseEnvelope<T>(res: Response): Promise<T> {
  // Some endpoints (e.g. DELETE) may return 204/empty â preserve "true" behaviour by treating undefined as void.
  const text = await res.text();
  let body: ApiEnvelope<T> | LegacyErrorResponse | T | null = null;
  if (text) {
    try {
      body = JSON.parse(text) as ApiEnvelope<T> | LegacyErrorResponse | T;
    } catch {
      body = null;
    }
  }

  if (!res.ok) {
    let code = `HTTP_${res.status}`;
    let message = userMessageForStatus(res.status);
    if (body && typeof body === 'object') {
      const env = body as ApiEnvelope<T>;
      if (env.ok === false && env.error) {
        code = env.error.code || code;
        message = env.error.message || message;
      } else {
        const legacy = body as LegacyErrorResponse;
        message = legacy.error || legacy.message || message;
      }
    }
    throw new ChartApiError(res.status, code, message);
  }

  if (body && typeof body === 'object' && 'ok' in body) {
    const env = body as ApiEnvelope<T>;
    if (env.ok === true) return env.data;
    throw new ChartApiError(res.status, env.error.code || `HTTP_${res.status}`, env.error.message || userMessageForStatus(res.status));
  }

  // No envelope (legacy/unwrapped) â return body as T to remain forward-compatible.
  return body as T;
}

async function get<T>(path: string, params?: Record<string, string | number | undefined>): Promise<T> {
  const url = new URL(path, window.location.origin);
  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== '') {
        url.searchParams.set(key, String(value));
      }
    }
  }

  const res = await fetch(url.pathname + url.search, { signal: timeoutSignal(REQUEST_TIMEOUT_MS) });
  return parseEnvelope<T>(res);
}

async function post<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: timeoutSignal(REQUEST_TIMEOUT_MS),
  });
  return parseEnvelope<T>(res);
}

async function put<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: timeoutSignal(REQUEST_TIMEOUT_MS),
  });
  return parseEnvelope<T>(res);
}

async function del(path: string): Promise<boolean> {
  const res = await fetch(`${API_BASE}${path}`, { method: 'DELETE', signal: timeoutSignal(REQUEST_TIMEOUT_MS) });
  await parseEnvelope<unknown>(res);
  return true;
}

// âââ Server â Client response mappers ââââââââââââââââââââââââââââââââââââââââââ

/**
 * Server bars response wraps bars in `{ bars: [...] }`.
 * Each bar has string-valued OHLC fields; we convert to numbers.
 */
interface ServerBarsResponse {
  bars: Array<{
    id?: number;
    instrumentId?: number;
    timeframe?: string;
    symbol?: string;
    timestamp: number;
    open: string | number;
    high: string | number;
    low: string | number;
    close: string | number;
    volume: number;
  }>;
}

function mapBarsResponse(raw: ServerBarsResponse, symbol: string, timeframe: Timeframe): BarsResponse {
  return {
    symbol,
    timeframe,
    bars: raw.bars.map((b) => ({
      timestamp: b.timestamp,
      open: Number(b.open),
      high: Number(b.high),
      low: Number(b.low),
      close: Number(b.close),
      volume: b.volume,
    })),
  };
}

/**
 * Server quote response wraps quote in `{ quote: {...} }`.
 * Quote fields are string-valued on the server; we convert to numbers.
 */
interface ServerQuoteResponse {
  quote: {
    id?: number;
    instrumentId?: number;
    symbol?: string;
    lastPrice: string | number;
    change: string | number;
    changePercent: string | number;
    marketStatus: string;
  };
}

function mapQuoteResponse(raw: ServerQuoteResponse): QuoteResponse {
  const q = raw.quote;
  return {
    symbol: q.symbol ?? '',
    lastPrice: Number(q.lastPrice),
    change: Number(q.change),
    changePercent: Number(q.changePercent),
    marketStatus: q.marketStatus,
  };
}

/**
 * Server indicator definitions response wraps in `{ indicators: [...] }`.
 * Schema/inputs fields are JSON strings on the server; we parse them.
 */
interface ServerIndicatorDefinition {
  id: number;
  key: string;
  name: string;
  category: string;
  inputsSchema: string;
  defaultInputs: string;
  paneType: string;
  isOverlay: number | boolean;
  isPaid: number | boolean;
}

interface ServerIndicatorsResponse {
  indicators: ServerIndicatorDefinition[];
}

function mapIndicatorDefinitions(raw: ServerIndicatorsResponse): IndicatorDefinition[] {
  return raw.indicators.map((d) => ({
    key: d.key,
    name: d.name,
    category: d.category,
    inputsSchema: JSON.parse(d.inputsSchema),
    defaultInputs: JSON.parse(d.defaultInputs),
    paneType: d.paneType as 'overlay' | 'pane',
    isOverlay: Boolean(d.isOverlay),
    isPaid: Boolean(d.isPaid),
  }));
}

/**
 * Server watchlist response wraps in `{ watchlists: [...] }`.
 * The server now enriches watchlist symbols with quote data in a `symbols` field.
 */
interface ServerWatchlistSymbol {
  symbol: string;
  exchange: string;
  companyName: string;
  lastPrice: number;
  change: number;
  changePercent: number;
}

interface ServerWatchlist {
  id: number;
  name: string;
  symbolsJson: string;
  symbols?: ServerWatchlistSymbol[];
}

interface ServerWatchlistsResponse {
  watchlists: ServerWatchlist[];
}

function mapWatchlists(raw: ServerWatchlistsResponse): Watchlist[] {
  return raw.watchlists.map((w) => ({
    id: String(w.id),
    name: w.name,
    // Prefer the server-enriched `symbols` array; fall back to parsing symbolsJson
    symbols: w.symbols
      ? w.symbols.map((s) => ({
          symbol: s.symbol,
          exchange: s.exchange,
          companyName: s.companyName,
          lastPrice: s.lastPrice,
          change: s.change,
          changePercent: s.changePercent,
        }))
      : (JSON.parse(w.symbolsJson) as Watchlist['symbols']),
    isBuiltIn: w.name === 'Default',
  }));
}

/**
 * Server drawing object has JSON string fields; we parse them.
 */
interface ServerDrawingObject {
  id: number;
  layoutId: number;
  toolType: string;
  pointsJson: string;
  styleJson: string | null;
  text: string | null;
  locked: number | boolean;
  visible: number | boolean;
  metadataJson: string | null;
}

function mapDrawingObject(d: ServerDrawingObject): DrawingObject {
  return {
    id: String(d.id),
    toolType: d.toolType as DrawingTool,
    points: JSON.parse(d.pointsJson) as DrawingPoint[],
    style: d.styleJson ? (JSON.parse(d.styleJson) as DrawingStyle) : {
      color: '#2962ff',
      lineWidth: 1,
      lineStyle: 'solid',
    },
    text: d.text ?? '',
    locked: Boolean(d.locked),
    visible: Boolean(d.visible),
    metadata: d.metadataJson ? (JSON.parse(d.metadataJson) as import('@features/chart/types').DrawingMetadata) : undefined,
  };
}

/**
 * Server chart layout has JSON string fields; we parse them.
 */
interface ServerChartLayout {
  id: number;
  symbol: string;
  timeframe: string;
  chartType: string;
  visibleRangeJson: string | null;
  indicatorsJson: string | null;
  drawingsJson: string | null;
  panesJson: string | null;
  settingsJson: string | null;
}

function mapChartLayout(l: ServerChartLayout): ChartLayout {
  return {
    id: String(l.id),
    symbol: l.symbol,
    timeframe: l.timeframe as Timeframe,
    chartType: l.chartType as ChartType,
    visibleRange: l.visibleRangeJson ? (JSON.parse(l.visibleRangeJson) as { from: number; to: number }) : null,
    indicators: l.indicatorsJson ? (JSON.parse(l.indicatorsJson) as ActiveIndicator[]) : [],
    drawings: l.drawingsJson ? (JSON.parse(l.drawingsJson) as DrawingObject[]) : [],
    panes: l.panesJson ? (JSON.parse(l.panesJson) as PaneConfig[]) : [{ id: 'main', type: 'main', height: 100 }],
    settings: l.settingsJson
      ? (JSON.parse(l.settingsJson) as ChartSettings)
      : {
          theme: 'dark',
          timezone: 'Etc/UTC',
          scaleMode: 'normal',
          showGrid: true,
          showCrosshair: true,
          showVolume: true,
          candleStyle: {
            upColor: '#26a69a',
            downColor: '#ef5350',
            upWickColor: '#26a69a',
            downWickColor: '#ef5350',
            upBorderVisible: false,
            downBorderVisible: false,
          },
        },
  };
}

