    id?: number;
    theme: string;
    timezone: string;
    scaleMode: string;
    showGrid: number | boolean;
    showCrosshair: number | boolean;
    showVolume: number | boolean;
    candleStyleJson: string | null;
  };
}

/**
 * Server workspace bootstrap response.
 * Settings use raw DB fields, watchlist has both symbolsJson and enriched symbols,
 * and indicator definitions have JSON string fields.
 */
interface ServerWorkspaceBootstrapResponse {
  symbol: string;
  timeframe: string;
  chartType: string;
  settings: {
    theme: string;
    timezone: string;
    scaleMode: string;
    showGrid: number | boolean;
    showCrosshair: number | boolean;
    showVolume: number | boolean;
    candleStyleJson: string | null;
  };
  watchlist: {
    id: number;
    name: string;
    symbolsJson: string;
    symbols?: ServerWatchlistSymbol[];
  };
  availableTimeframes: string[];
  availableChartTypes: string[];
  indicatorDefinitions: ServerIndicatorDefinition[];
}

function mapWorkspaceBootstrap(raw: ServerWorkspaceBootstrapResponse): WorkspaceBootstrapResponse {
  const defaultCandleStyle = {
    upColor: '#26a69a',
    downColor: '#ef5350',
    upWickColor: '#26a69a',
    downWickColor: '#ef5350',
    upBorderVisible: false,
    downBorderVisible: false,
  };

  // Build watchlist symbols â prefer server-enriched array, fall back to parsing symbolsJson
  let watchlistSymbols: Watchlist['symbols'];
  if (raw.watchlist.symbols && raw.watchlist.symbols.length > 0) {
    watchlistSymbols = raw.watchlist.symbols.map((s) => ({
      symbol: s.symbol,
      exchange: s.exchange,
      companyName: s.companyName,
      lastPrice: s.lastPrice,
      change: s.change,
      changePercent: s.changePercent,
    }));
  } else {
    watchlistSymbols = JSON.parse(raw.watchlist.symbolsJson) as Watchlist['symbols'];
  }

  return {
    symbol: raw.symbol,
    timeframe: raw.timeframe as Timeframe,
    chartType: raw.chartType as ChartType,
    settings: {
      theme: raw.settings.theme as 'dark' | 'light',
      timezone: raw.settings.timezone,
      scaleMode: raw.settings.scaleMode as ChartSettings['scaleMode'],
      showGrid: Boolean(raw.settings.showGrid),
      showCrosshair: Boolean(raw.settings.showCrosshair),
      showVolume: Boolean(raw.settings.showVolume),
      candleStyle: raw.settings.candleStyleJson
        ? JSON.parse(raw.settings.candleStyleJson)
        : defaultCandleStyle,
    },
    watchlist: {
      id: String(raw.watchlist.id),
      name: raw.watchlist.name,
      symbols: watchlistSymbols,
      isBuiltIn: raw.watchlist.name === 'Default',
    },
    availableTimeframes: raw.availableTimeframes as Timeframe[],
    availableChartTypes: raw.availableChartTypes as ChartType[],
    indicatorDefinitions: mapIndicatorDefinitions({ indicators: raw.indicatorDefinitions }),
  };
}

function mapSettingsResponse(raw: ServerSettingsResponse): SettingsResponse {
  const s = raw.settings;
  const defaultCandleStyle = {
    upColor: '#26a69a',
    downColor: '#ef5350',
    upWickColor: '#26a69a',
    downWickColor: '#ef5350',
    upBorderVisible: false,
    downBorderVisible: false,
  };
  return {
    theme: s.theme as 'dark' | 'light',
    timezone: s.timezone,
    scaleMode: s.scaleMode as 'normal' | 'logarithmic' | 'percentage' | 'indexed_to_100',
    showGrid: Boolean(s.showGrid),
    showCrosshair: Boolean(s.showCrosshair),
    showVolume: Boolean(s.showVolume),
    candleStyle: s.candleStyleJson ? JSON.parse(s.candleStyleJson) : defaultCandleStyle,
  };
}

/**
 * Server template entry has payloadJson as a string; we parse it.
 */
interface ServerTemplateEntry {
  id: number;
  name: string;
  family: string;
  payloadJson: string;
  isBuiltIn: number | boolean;
  isAuthGated: number | boolean;
  updatedAt: number | null;
}

function mapTemplateEntry(t: ServerTemplateEntry): TemplateEntry {
  return {
    id: String(t.id),
    name: t.name,
    family: t.family as TemplateFamily,
    payload: JSON.parse(t.payloadJson) as Record<string, unknown>,
    isBuiltIn: Boolean(t.isBuiltIn),
    isAuthGated: Boolean(t.isAuthGated),
    updatedAt: t.updatedAt ?? 0,
  };
}

