  // ââ Layout Management ââââââââââââââââââââââââââââââââââââââââââââââââââââââ

  /**
   * Rename a chart layout.
   * PUT /api/chart/layouts/:id/rename
   */
  async renameLayout(id: string, name: string): Promise<ChartLayout> {
    const raw = await put<{ layout: ServerChartLayout }>(`/layouts/${encodeURIComponent(id)}/rename`, { name });
    return mapChartLayout(raw.layout);
  },

  /**
   * Delete a chart layout.
   * DELETE /api/chart/layouts/:id
   */
  async deleteLayout(id: string): Promise<boolean> {
    return del(`/layouts/${encodeURIComponent(id)}`);
  },

  /**
   * Update a chart layout (save current state).
   * PUT /api/chart/layouts/:id
   */
  async updateLayout(id: string, data: Partial<CreateLayoutRequest>): Promise<ChartLayout> {
    const body: Record<string, unknown> = {};
    if (data.symbol !== undefined) body.symbol = data.symbol;
    if (data.timeframe !== undefined) body.timeframe = data.timeframe;
    if (data.chartType !== undefined) body.chartType = data.chartType;
    if (data.visibleRange !== undefined) body.visibleRangeJson = JSON.stringify(data.visibleRange);
    if (data.indicators !== undefined) body.indicatorsJson = JSON.stringify(data.indicators);
    if (data.drawings !== undefined) body.drawingsJson = JSON.stringify(data.drawings);
    if (data.panes !== undefined) body.panesJson = JSON.stringify(data.panes);
    if (data.settings !== undefined) body.settingsJson = JSON.stringify(data.settings);
    const raw = await put<{ layout: ServerChartLayout }>(`/layouts/${encodeURIComponent(id)}`, body);
    return mapChartLayout(raw.layout);
  },
} as const;

