// âââ Placement behavior classification ââââââââââââââââââââââââââââââââââââââ

type PlacementCategory = 'single' | 'two-click' | 'multi-point' | 'drag' | 'freehand';

/**
 * Determine which interaction model a tool uses based on its registry config.
 * Falls back to 'two-click' for unknown tools.
 */
function getPlacementCategory(tool: DrawingTool): PlacementCategory {
  const config = DRAWING_TOOL_REGISTRY.find((t) => t.id === tool);
  if (!config) return 'two-click';

  switch (config.placementBehavior) {
    case 'click':
      // Single-click tools: horizontal_line, vertical_line, annotations, icons
      // But text_note is special â needs text input before commit, so treat as single
      return 'single';
    case 'drag':
      return 'drag';
    case 'freehand':
      return 'freehand';
    case 'click-click':
      // Differentiate between two-click and multi-point based on pointsModel
      if (config.pointsModel === 'multi-point') return 'multi-point';
      return 'two-click';
    default:
      return 'two-click';
  }
}

// âââ Coordinate conversion helpers ââââââââââââââââââââââââââââââââââââââââââ

/**
 * Convert a mouse event on the chart container to chart coordinates (price, time).
 * Returns null if the chart API is unavailable or the point is outside the chart.
 */
function eventToChartCoords(
  event: MouseEvent,
  api: IChartApi,
  mainSeries: ISeriesApi<'Candlestick' | 'Bar' | 'Line' | 'Area' | 'Baseline'>,
): DrawingPoint | null {
  const target = event.currentTarget as HTMLElement;
  if (!target) return null;

  const rect = target.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  // Convert pixel x to time via time scale
  const timeScale = api.timeScale();
  const timeCoord = timeScale.coordinateToTime(x);
  if (timeCoord === null) return null;

  // Convert pixel y to price via the main series' price scale
  const priceCoord = mainSeries.coordinateToPrice(y);
  if (priceCoord === null) return null;

  // Convert Time to numeric timestamp
  const timeNumber = typeof timeCoord === 'number'
    ? timeCoord
    : (timeCoord as unknown as number);

  return {
    x,
    y,
    price: priceCoord,
    time: timeNumber,
  };
}

// âââ Generate unique ID for drawings ââââââââââââââââââââââââââââââââââââââââ

let drawingIdCounter = 0;
function generateDrawingId(): string {
  drawingIdCounter += 1;
  return `drawing_${Date.now()}_${drawingIdCounter}`;
}

// âââ Freehand throttle constant âââââââââââââââââââââââââââââââââââââââââââââ

/** Minimum interval between freehand samples (ms) */
const FREEHAND_THROTTLE_MS = 16;

/** Maximum points per freehand stroke */
const FREEHAND_MAX_POINTS = 500;

// âââ Hook âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/** The main series types supported by ChartRendererAdapter */
type MainSeriesType = 'Candlestick' | 'Bar' | 'Line' | 'Area' | 'Baseline';

export interface UseDrawingCreationOptions {
  /** The lightweight-charts IChartApi instance */
  chartApi: IChartApi | null;
  /** The main series API for price coordinate conversion */
  mainSeries: ISeriesApi<MainSeriesType> | null;
  /** The DOM element that contains the chart (for attaching event listeners) */
  containerElement: HTMLElement | null;
}

export interface UseDrawingCreationResult {
  /** The pending drawing being created (has first point but not second) */
  pendingDrawing: PendingDrawing | null;
  /** Callback when a text note's content is submitted */
  submitTextNote: (text: string) => void;
  /** Cancel the current drawing operation */
  cancelDrawing: () => void;
  /** Finish a multi-point drawing early (Enter key or double-click) */
  finishMultiPointDrawing: () => void;
}

export function useDrawingCreation(
  options: UseDrawingCreationOptions,
): UseDrawingCreationResult {
  const { chartApi, mainSeries, containerElement } = options;

  const [pendingDrawing, setPendingDrawing] = useState<PendingDrawing | null>(null);

  // Ref for freehand throttle â avoids re-renders on every mousemove
  const lastFreehandSampleRef = useRef<number>(0);

  // Store actions
  const addDrawing = useChartStore((s) => s.addDrawing);
  const selectedTool = useChartStore((s) => s.selectedTool);
  const drawingMode = useChartStore((s) => s.drawingMode);
  const setSelectedTool = useChartStore((s) => s.setSelectedTool);

  // ââ Commit a drawing to the store and optionally the API âââââââââââââââââââ

  const commitDrawing = useCallback(
    (toolType: DrawingTool, points: DrawingPoint[], text: string = '', metadata?: DrawingMetadata) => {
      const style: DrawingStyle = DEFAULT_STYLES[toolType] ?? DEFAULT_STYLES.trend_line!;

      const drawing: DrawingObject = {
        id: generateDrawingId(),
        toolType,
        points,
        style,
        text,
        locked: false,
        visible: true,
        ...(metadata ? { metadata } : {}),
      };

      // Add to store (pushes undo history)
      addDrawing(drawing);

      // Persist to API (fire-and-forget â don't block UI)
      persistDrawingToApi(drawing);

      // Reset pending state
      setPendingDrawing(null);
    },
    [addDrawing],
  );

  // ââ Handle text note submission ââââââââââââââââââââââââââââââââââââââââââââ

  const submitTextNote = useCallback(
    (text: string) => {
      if (!pendingDrawing || pendingDrawing.toolType !== 'text_note' || pendingDrawing.points.length === 0) return;

      commitDrawing('text_note', [pendingDrawing.points[0]!], text);
    },
    [pendingDrawing, commitDrawing],
  );

  // ââ Cancel the current drawing âââââââââââââââââââââââââââââââââââââââââââââ

  const cancelDrawing = useCallback(() => {
    setPendingDrawing(null);
  }, []);

  // ââ Finish a multi-point drawing early (Enter / dblclick) ââââââââââââââââââ

  const finishMultiPointDrawing = useCallback(() => {
    if (!pendingDrawing) return;
    const { toolType, points } = pendingDrawing;
    const spec = MULTI_POINT_SPECS[toolType];
    if (!spec) return;

    if (points.length >= spec.minPoints) {
      commitDrawing(toolType, points);
    }
  }, [pendingDrawing, commitDrawing]);

  // âââ 1. handleSingleClick ââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Single-click tools: one click commits the drawing immediately.
  // Special case: text_note defers commit until text is submitted.

  const handleSingleClick = useCallback(
    (tool: DrawingTool, point: DrawingPoint) => {
      if (tool === 'text_note') {
        // Defer commit â DrawingOverlay shows a text input
        setPendingDrawing({ toolType: tool, points: [point], isDragging: false });
        return;
      }
      // All other single-click tools commit immediately
      commitDrawing(tool, [point]);
    },
    [commitDrawing],
  );

  // âââ 2. handleTwoClick âââââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Two-click tools: first click sets P1, second click sets P2 and commits.

  const handleTwoClick = useCallback(
    (tool: DrawingTool, point: DrawingPoint) => {
      setPendingDrawing((prev) => {
        if (!prev || prev.toolType !== tool || prev.isDragging || prev.points.length >= 2) {
          // Start a new drawing with the first click
          return { toolType: tool, points: [point], isDragging: false };
        }
        if (prev.points.length === 1) {
          // Second click â complete the drawing
          const points = [prev.points[0]!, point];
          // Commit is done via useEffect below to avoid setState-in-setState
          // We set the pending with 2 points, then the effect commits it
          return { toolType: tool, points, isDragging: false };
        }
        return prev;
      });
    },
    [],
  );

  // Effect to auto-commit two-click drawings when they reach 2 points
  useEffect(() => {
    if (!pendingDrawing) return;
    const { toolType, points, isDragging } = pendingDrawing;
    if (isDragging) return;

    const category = getPlacementCategory(toolType);
    if (category === 'two-click' && points.length === 2) {
      commitDrawing(toolType, points);
    }
  }, [pendingDrawing, commitDrawing]);

  // âââ 3. handleMultiPoint âââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Multi-point tools: collect points via successive clicks.
  // Auto-commits when expected count reached. Enter / double-click can
  // early-commit if minPoints threshold is met.

  const handleMultiPoint = useCallback(
    (tool: DrawingTool, point: DrawingPoint) => {
      const spec = MULTI_POINT_SPECS[tool];
      if (!spec) return; // Unknown multi-point tool â ignore

      setPendingDrawing((prev) => {
        if (!prev || prev.toolType !== tool || prev.isDragging) {
          // Start a new multi-point drawing
          return { toolType: tool, points: [point], isDragging: false };
        }
        const next = [...prev.points, point];
        if (next.length >= spec.points) {
          // Auto-commit at expected count â effect handles it
          return { toolType: tool, points: next, isDragging: false };
        }
        return { toolType: tool, points: next, isDragging: false };
      });
    },
    [],
  );

  // Effect to auto-commit multi-point drawings when they reach expected count
  useEffect(() => {
    if (!pendingDrawing) return;
    const { toolType, points, isDragging } = pendingDrawing;
    if (isDragging) return;

    const category = getPlacementCategory(toolType);
    if (category === 'multi-point') {
      const spec = MULTI_POINT_SPECS[toolType];
      if (spec && points.length >= spec.points) {
        commitDrawing(toolType, points);
      }
    }
  }, [pendingDrawing, commitDrawing]);

  // âââ 4. handleDrag âââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Drag tools: mousedown sets P1, mousemove updates P2 (live preview),
  // mouseup commits.

  const handleDragStart = useCallback(
    (tool: DrawingTool, point: DrawingPoint) => {
      setPendingDrawing({ toolType: tool, points: [point, point], isDragging: true });
    },
    [],
  );

  const handleDragMove = useCallback(
    (point: DrawingPoint) => {
      setPendingDrawing((prev) => {
        if (!prev || !prev.isDragging || prev.points.length < 2) return prev;
        return { ...prev, points: [prev.points[0]!, point] };
      });
    },
    [],
  );

  const handleDragEnd = useCallback(
    (point: DrawingPoint) => {
      setPendingDrawing((prev) => {
        if (!prev || !prev.isDragging || prev.points.length < 1) return null;
        const points = prev.points.length >= 2
          ? [prev.points[0]!, point]
          : [prev.points[0]!, point];
        // Commit via effect by setting isDragging=false
        return { ...prev, points, isDragging: false };
      });
    },
    [],
  );

  // Effect to commit drag drawings when drag ends (isDragging transitions to false)
  useEffect(() => {
    if (!pendingDrawing || pendingDrawing.isDragging) return;
    const { toolType, points } = pendingDrawing;
    const category = getPlacementCategory(toolType);
    if (category === 'drag' && points.length >= 2) {
      commitDrawing(toolType, points);
    }
  }, [pendingDrawing, commitDrawing]);

  // âââ 5. handleFreehand âââââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Freehand tools: mousedown starts stroke, mousemove adds samples
  // (throttled to FREEHAND_THROTTLE_MS), mouseup commits.

  const handleFreehandStart = useCallback(
    (tool: DrawingTool, point: DrawingPoint) => {
      lastFreehandSampleRef.current = Date.now();
      setPendingDrawing({ toolType: tool, points: [point], isDragging: true });
    },
    [],
  );

  const handleFreehandMove = useCallback(
    (point: DrawingPoint) => {
      const now = Date.now();
      if (now - lastFreehandSampleRef.current < FREEHAND_THROTTLE_MS) return;
      lastFreehandSampleRef.current = now;

      setPendingDrawing((prev) => {
        if (!prev || !prev.isDragging) return prev;
        if (prev.points.length >= FREEHAND_MAX_POINTS) {
          if (prev.points.length === FREEHAND_MAX_POINTS) {
            console.warn(`Freehand stroke reached ${FREEHAND_MAX_POINTS} points â truncating further samples`);
          }
          return prev;
        }
        return { ...prev, points: [...prev.points, point] };
      });
    },
    [],
  );

  const handleFreehandEnd = useCallback(
    () => {
      setPendingDrawing((prev) => {
        if (!prev || !prev.isDragging) return null;
        // Commit via effect by setting isDragging=false
        return { ...prev, isDragging: false };
      });
    },
    [],
  );

  // Effect to commit freehand drawings when stroke ends
  useEffect(() => {
    if (!pendingDrawing || pendingDrawing.isDragging) return;
    const { toolType, points } = pendingDrawing;
    const category = getPlacementCategory(toolType);
    if (category === 'freehand' && points.length >= 1) {
      commitDrawing(toolType, points);
    }
  }, [pendingDrawing, commitDrawing]);

  // ââ Main click dispatch ââââââââââââââââââââââââââââââââââââââââââââââââââââ
  //
  // Routes mousedown to the appropriate interaction model handler.
  // Drag and freehand tools only initiate on mousedown; mousemove and mouseup
  // are handled separately in the mouse event effect below.

  const handleChartMouseDown = useCallback(
    (event: MouseEvent) => {
      if (!chartApi || !mainSeries || !drawingMode || !selectedTool) return;
      // Only process clicks from the primary button
      if (event.button !== 0) return;

      // Cursor and crosshair don't create drawings
      if (selectedTool === 'cursor' || selectedTool === 'crosshair') return;

      const point = eventToChartCoords(event, chartApi, mainSeries);
      if (!point) return;

      const category = getPlacementCategory(selectedTool);

      switch (category) {
        case 'single':
          handleSingleClick(selectedTool, point);
          break;
        case 'two-click':
          handleTwoClick(selectedTool, point);
          break;
        case 'multi-point':
          handleMultiPoint(selectedTool, point);
          break;
        case 'drag':
          handleDragStart(selectedTool, point);
          break;
        case 'freehand':
          handleFreehandStart(selectedTool, point);
          break;
      }
    },
    [chartApi, mainSeries, drawingMode, selectedTool, handleSingleClick, handleTwoClick, handleMultiPoint, handleDragStart, handleFreehandStart],
  );

  // ââ Handle double-click for multi-point early completion âââââââââââââââââââ

  const handleChartDblClick = useCallback(
    (event: MouseEvent) => {
      if (!chartApi || !mainSeries || !drawingMode || !selectedTool) return;
      if (!pendingDrawing) return;

      const category = getPlacementCategory(selectedTool);
      if (category !== 'multi-point') return;

      // Double-click commits the multi-point drawing if minPoints met
      const spec = MULTI_POINT_SPECS[selectedTool];
      if (spec && pendingDrawing.points.length >= spec.minPoints) {
        event.preventDefault();
        event.stopPropagation();
        commitDrawing(selectedTool, pendingDrawing.points);
      }
    },
    [chartApi, mainSeries, drawingMode, selectedTool, pendingDrawing, commitDrawing],
  );

  // ââ Handle mousemove for drag and freehand âââââââââââââââââââââââââââââââââ

  const handleChartMouseMove = useCallback(
    (event: MouseEvent) => {
      if (!chartApi || !mainSeries || !pendingDrawing || !pendingDrawing.isDragging) return;

      const point = eventToChartCoords(event, chartApi, mainSeries);
      if (!point) return;

      const category = getPlacementCategory(pendingDrawing.toolType);

      if (category === 'drag') {
        handleDragMove(point);
      } else if (category === 'freehand') {
        handleFreehandMove(point);
      }
    },
    [chartApi, mainSeries, pendingDrawing, handleDragMove, handleFreehandMove],
  );

  // ââ Handle mouseup for drag and freehand âââââââââââââââââââââââââââââââââââ

  const handleChartMouseUp = useCallback(
    (event: MouseEvent) => {
      if (!pendingDrawing || !pendingDrawing.isDragging) return;

      const category = getPlacementCategory(pendingDrawing.toolType);

      if (category === 'drag') {
        if (chartApi && mainSeries) {
          const point = eventToChartCoords(event, chartApi, mainSeries);
          if (point) {
            handleDragEnd(point);
          } else {
            handleDragEnd(pendingDrawing.points[0]!); // Fallback: commit with same point
          }
        }
      } else if (category === 'freehand') {
        handleFreehandEnd();
      }
    },
    [chartApi, mainSeries, pendingDrawing, handleDragEnd, handleFreehandEnd],
  );

  // ââ Handle Escape key to cancel drawing ââââââââââââââââââââââââââââââââââââ
  // ââ Handle Enter key to commit multi-point drawings early ââââââââââââââââââ

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && pendingDrawing) {
        setPendingDrawing(null);
        setSelectedTool('cursor');
      }
      if (event.key === 'Enter' && pendingDrawing) {
        const category = getPlacementCategory(pendingDrawing.toolType);
        if (category === 'multi-point') {
          const spec = MULTI_POINT_SPECS[pendingDrawing.toolType];
          if (spec && pendingDrawing.points.length >= spec.minPoints) {
            event.preventDefault();
            commitDrawing(pendingDrawing.toolType, pendingDrawing.points);
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pendingDrawing, setSelectedTool, commitDrawing]);

  // ââ Attach event handlers to the chart container âââââââââââââââââââââââââââ

  useEffect(() => {
    const el = containerElement;
    if (!el) return;

    el.addEventListener('mousedown', handleChartMouseDown);
    el.addEventListener('dblclick', handleChartDblClick);
    el.addEventListener('mousemove', handleChartMouseMove);
    el.addEventListener('mouseup', handleChartMouseUp);

    return () => {
      el.removeEventListener('mousedown', handleChartMouseDown);
      el.removeEventListener('dblclick', handleChartDblClick);
      el.removeEventListener('mousemove', handleChartMouseMove);
      el.removeEventListener('mouseup', handleChartMouseUp);
    };
  }, [containerElement, handleChartMouseDown, handleChartDblClick, handleChartMouseMove, handleChartMouseUp]);

  // ââ Clean up pending when tool changes to non-drawing ââââââââââââââââââââââ

  useEffect(() => {
    if (!drawingMode) {
      setPendingDrawing(null);
    }
  }, [drawingMode]);

  return {
    pendingDrawing,
    submitTextNote,
    cancelDrawing,
    finishMultiPointDrawing,
  };
}

// âââ API persistence helper (fire-and-forget) ââââââââââââââââââââââââââââââ

async function persistDrawingToApi(drawing: DrawingObject): Promise<void> {
  try {
    // Use a default layoutId of "1" â the local replica doesn't have real
    // multi-layout support, so all drawings go to the default layout.
    await chartApi.createDrawing({
      layoutId: '1',
      toolType: drawing.toolType,
      points: drawing.points,
      style: drawing.style,
      text: drawing.text,
      locked: drawing.locked,
      visible: drawing.visible,
      metadata: drawing.metadata,
    });
  } catch {
    // Silently ignore â drawing is already in the local store
  }
}

