  parallel_channel: { points: 3, minPoints: 3 },
  ascending_channel: { points: 3, minPoints: 3 },
  descending_channel: { points: 3, minPoints: 3 },
  flat_channel: { points: 3, minPoints: 3 },
  // Pitchfork (3 points per PRD Â§3.21)
  andrews_pitchfork: { points: 3, minPoints: 3 },
  schiff_pitchfork: { points: 3, minPoints: 3 },
  modified_schiff_pitchfork: { points: 3, minPoints: 3 },
  // Patterns (per PRD Â§3 Phase 3)
  elliott_impulse_wave: { points: 6, minPoints: 5 },
