  cypher_pattern: { points: 5, minPoints: 4 },
  abc_pattern: { points: 4, minPoints: 3 },
  three_drives: { points: 7, minPoints: 5 },
  // Shapes (multi-point per PRD Â§3.38)
  triangle_shape: { points: 3, minPoints: 3 },
  parallelogram: { points: 3, minPoints: 3 },
  // Position (measured_move is 3 points per PRD Â§3.37)
  measured_move: { points: 3, minPoints: 3 },
  // Callout (2 points: text position + anchor per PRD Â§3.7-3.12)
  callout: { points: 2, minPoints: 2 },
};

// âââ Default drawing styles per tool ââââââââââââââââââââââââââââââââââââââââ

