  triangle_shape: { color: '#2962ff', lineWidth: 1, lineStyle: 'solid', fill: 'rgba(41, 98, 255, 0.1)' },
  parallelogram: { color: '#2962ff', lineWidth: 1, lineStyle: 'solid', fill: 'rgba(41, 98, 255, 0.1)' },
  // Channels
