function renderRectangle(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  const dashArray = style.lineStyle === 'dashed'
    ? '6,4'
    : style.lineStyle === 'dotted'
      ? '2,3'
      : undefined;

  return (
    <rect
      x={x}
      y={y}
      width={width}
      height={height}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      strokeDasharray={dashArray}
      fill={style.fill ?? 'none'}
    />
  );
}

function renderTextNote(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  text: string,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 1 || !text) return null;

  const p = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p) return null;

  return (
    <text
      x={p.x + 6}
      y={p.y - 6}
      fill={style.color}
