    >
      {text}
    </text>
  );
}

/**
 * Compute measure values (Îprice, Îprice%, Îbars) from two drawing points.
 */
function computeMeasureValues(p1: DrawingPoint, p2: DrawingPoint): {
  deltaPrice: number;
  deltaPrct: number;
  deltaBars: number;
} {
  const deltaPrice = p2.price - p1.price;
  const deltaPrct = p1.price !== 0 ? (deltaPrice / Math.abs(p1.price)) * 100 : 0;
  // Bars are the time difference in chart time units. Each bar = 1 unit in
  // most lightweight-charts configurations, so we use the absolute time diff.
  const deltaBars = Math.abs(Math.round(p2.time - p1.time));
  return { deltaPrice, deltaPrct, deltaBars };
}

/**
 * Format a price delta with sign and decimal places.
 */
function formatDeltaPrice(value: number): string {
  const sign = value >= 0 ? '+' : '';
  return `${sign}${value.toFixed(2)}`;
}

/**
 * Format a percentage delta with sign.
 */
function formatDeltaPrct(value: number): string {
  const sign = value >= 0 ? '+' : '';
  return `${sign}${value.toFixed(2)}%`;
}

/**
 * Render the measure tool: dashed rectangle between P1 and P2, with a
 * centered text block showing Îprice, Îprice%, and Îbars.
 * If metadata is available, uses pre-computed values; otherwise computes
 * from points directly (so preview during drag also works).
 */
function renderMeasure(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  metadata: DrawingMetadata | undefined,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  // Use metadata if available (committed drawing), otherwise compute (preview)
  const measureMeta = metadata as MeasureMetadata | undefined;
  const deltaPrice = measureMeta?.deltaPrice ?? points[1]!.price - points[0]!.price;
  const deltaPrct = measureMeta?.deltaPrct ?? (points[0]!.price !== 0
    ? ((points[1]!.price - points[0]!.price) / Math.abs(points[0]!.price)) * 100
    : 0);
  const deltaBars = measureMeta?.deltaBars ?? Math.abs(Math.round(points[1]!.time - points[0]!.time));

  // Center text position
  const cx = x + width / 2;
  const cy = y + height / 2;

  const fontFamily = "-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif";

  return (
    <g>
      {/* Dashed rectangle */}
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="6,4"
        fill={style.fill ?? 'rgba(120, 123, 134, 0.05)'}
      />
      {/* Delta values text block â centered in rectangle */}
      <text
        x={cx}
        y={cy - 14}
        fill={style.color}
        fontSize={12}
        fontFamily={fontFamily}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {formatDeltaPrice(deltaPrice)} ({formatDeltaPrct(deltaPrct)})
      </text>
      <text
        x={cx}
        y={cy + 4}
        fill={style.color}
        fontSize={12}
        fontFamily={fontFamily}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {deltaBars} bars
      </text>
    </g>
  );
}

function renderEmojiIcon(
  drawing: DrawingObject,
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (drawing.points.length < 1) return null;

  const p = chartToPixel(drawing.points[0]!, chartApi, mainSeries);
  if (!p) return null;

  const metadata = drawing.metadata as EmojiMetadata | undefined;
  const emoji = metadata?.emoji ?? 'â­';

  return (
    <text
      x={p.x}
      y={p.y}
      fill={style.color}
      fontSize={style.fontSize ?? 20}
      textAnchor="middle"
      dominantBaseline="central"
    >
      {emoji}
    </text>
  );
}

function renderImageEmbed(
  drawing: DrawingObject,
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (drawing.points.length < 1) return null;

  const p = chartToPixel(drawing.points[0]!, chartApi, mainSeries);
  if (!p) return null;

  const metadata = drawing.metadata as ImageMetadata | undefined;
  const url = metadata?.url ?? '';
  const w = metadata?.w ?? 64;
  const h = metadata?.h ?? 64;
  const isValidUrl = url.startsWith('https://') || url.startsWith('data:image/');

  if (isValidUrl) {
    return (
      <image
        href={url}
        x={p.x - w / 2}
        y={p.y - h / 2}
        width={w}
        height={h}
        opacity={style.opacity ?? 1}
      />
    );
  }

  // Invalid or missing URL: placeholder rect + alt text
  return (
    <g>
      <rect
        x={p.x - w / 2}
        y={p.y - h / 2}
        width={w}
        height={h}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="4,3"
        fill="rgba(120, 123, 134, 0.1)"
      />
      <text
        x={p.x}
        y={p.y}
        fill={style.color}
        fontSize={10}
        textAnchor="middle"
        dominantBaseline="central"
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {url ? 'Invalid URL' : 'No image'}
      </text>
    </g>
  );
}

// âââ Pending drawing renderers ââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Render a freehand brush path as an SVG <path> connecting all sampled points.
 * Used for brush / highlighter / scribble during and after stroke.
 */
function renderFreehandPath(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length < 2) return null;

  const d = pixels
    .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
    .join(' ');

  return (
    <path
      d={d}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={style.opacity ?? 1}
    />
  );
}

/**
 * Render a drag preview based on the tool type.
 * During drag, shows the shape between P1 and the current mouse position.
 */
function renderDragPreview(
  toolType: string,
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  _containerWidth: number,
  _containerHeight: number,
) {
  // Range/measure tools: dashed rectangle preview
  if (
    toolType === 'range_tool' ||
    toolType === 'date_range' ||
    toolType === 'price_range'
  ) {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Measure: dashed rectangle with live delta values
  if (toolType === 'measure') {
    return renderMeasure(points, style, undefined, chartApi, mainSeries);
  }

  // Rectangle: standard rectangle preview
  if (toolType === 'rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Ellipse/circle/rounded_rectangle: rectangle bounding box as placeholder
  if (toolType === 'ellipse' || toolType === 'circle' || toolType === 'rounded_rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Generic drag fallback: show rectangle
  return renderRectangle(points, style, chartApi, mainSeries);
}

/**
 * Render a multi-point tool preview: dots at each placed point + dashed
 * polyline connecting them, so the user sees their progress while placing
 * additional points.
 */
function renderMultiPointPreview(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length === 0) return null;

  const elements: React.ReactNode[] = [];

  // Dots at each point
  for (const p of pixels) {
    elements.push(
      <circle
        key={`dot-${p.x}-${p.y}`}
        cx={p.x}
        cy={p.y}
        r={3}
        fill={style.color}
        opacity={0.7}
      />,
    );
  }

  // Dashed polyline connecting placed points
  if (pixels.length >= 2) {
    const d = pixels
      .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
      .join(' ');
    elements.push(
      <path
        key="polyline"
        d={d}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="6,4"
        fill="none"
        opacity={0.7}
      />,
    );
  }

  return <g>{elements}</g>;
}

// âââ TextNoteInput â DOM overlay for text input on the chart ââââââââââââââââ

interface TextNoteInputProps {
  x: number;
  y: number;
  visible: boolean;
  onSubmit: (text: string) => void;
  onCancel: () => void;
}

function TextNoteInput({ x, y, visible, onSubmit, onCancel }: TextNoteInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (visible && inputRef.current) {
      inputRef.current.focus();
    }
  }, [visible]);

  if (!visible) return null;

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      const text = (event.target as HTMLInputElement).value.trim();
      if (text) {
        onSubmit(text);
      } else {
        onCancel();
      }
    } else if (event.key === 'Escape') {
      onCancel();
    }
  };

  const handleBlur = (event: React.FocusEvent<HTMLInputElement>) => {
    const text = event.target.value.trim();
    if (text) {
      onSubmit(text);
    } else {
      onCancel();
    }
  };

  return (
    <input
      ref={inputRef}
      type="text"
      className="drawing-overlay__text-input"
      data-testid="drawing-text-note-input"
      style={{
        position: 'absolute',
        left: x + 6,
        top: y - 14,
        zIndex: 20,
        pointerEvents: 'auto',
        background: 'rgba(19, 23, 34, 0.9)',
        border: '1px solid #2962ff',
        color: '#d1d4dc',
        fontSize: 14,
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif",
        padding: '2px 6px',
        borderRadius: 2,
        outline: 'none',
        minWidth: 120,
      }}
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
      aria-label="Enter text note"
      placeholder="Type text..."
    />
  );
}

