// pointsModel field identifies which tools are multi-point; this table
// provides the exact counts and minimum-commit thresholds.

export interface MultiPointSpec {
  /** Exact number of points that auto-commits the drawing */
  points: number;
  /** Minimum points required for early (Enter / dblclick) commit */
  minPoints: number;
}

export const MULTI_POINT_SPECS: Record<string, MultiPointSpec> = {
