  const elements: React.ReactNode[] = [];

  // Leader line to anchor (P2 or metadata anchor)
  if (points.length >= 2) {
    const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
