        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  } else if (drawing.metadata?.kind === 'callout') {
    const anchor = drawing.metadata.anchor;
    const p2 = chartToPixel(anchor, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
          y1={p1.y}
          x2={p2.x}
          y2={p2.y}
          stroke={style.color}
          strokeWidth={1}
          strokeDasharray="4,3"
        />,
      );
      elements.push(
        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  }

  // Text at P1
  if (text) {
    const fontSize = style.fontSize ?? 14;
    elements.push(
      <text
        key="callout-text"
