    );
  }

  // Invalid or missing URL: placeholder rect + alt text
  return (
    <g>
      <rect
        x={p.x - w / 2}
        y={p.y - h / 2}
        width={w}
        height={h}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="4,3"
