/** Callout â text note with leader line to anchor point */
function renderCallout(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  text: string,
  drawing: DrawingObject,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 1) return null;
  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p1) return null;

  const elements: React.ReactNode[] = [];

  // Leader line to anchor (P2 or metadata anchor)
  if (points.length >= 2) {
    const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
          y1={p1.y}
          x2={p2.x}
          y2={p2.y}
          stroke={style.color}
          strokeWidth={1}
          strokeDasharray="4,3"
        />,
      );
      // Small dot at the anchor point
      elements.push(
        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  } else if (drawing.metadata?.kind === 'callout') {
    const anchor = drawing.metadata.anchor;
    const p2 = chartToPixel(anchor, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
          y1={p1.y}
          x2={p2.x}
          y2={p2.y}
          stroke={style.color}
          strokeWidth={1}
          strokeDasharray="4,3"
        />,
      );
      elements.push(
        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  }

  // Text at P1
  if (text) {
    const fontSize = style.fontSize ?? 14;
    elements.push(
      <text
        key="callout-text"
        x={p1.x + 6}
        y={p1.y - 6}
        fill={style.color}
        fontSize={fontSize}
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {text}
      </text>,
    );
  }

  return elements.length > 0 ? <g>{elements}</g> : null;
}

