/**
 * DrawingOverlay â SVG overlay that renders all drawing objects on the chart.
 *
 * This component renders an absolute-positioned SVG layer on top of the chart
 * canvas. It reads drawings from the Zustand store and converts chart
 * coordinates (price, time) to pixel coordinates using the lightweight-charts
 * API. It also renders the "in-progress" drawing (pending from useDrawingCreation)
 * and a text input for text notes.
 *
 * Supported drawing types:
 * - Trend line: line between two (time, price) points
 * - Horizontal line: horizontal line spanning the full visible time range at a price
 * - Vertical line: vertical line spanning the full visible price range at a time
 * - Rectangle: rectangle between two (time, price) corner points
 * - Text note: text label at a (time, price) position
 */

import { useEffect, useRef, useState, useCallback } from 'react';
import type { IChartApi, ISeriesApi } from 'lightweight-charts';
import { useChartStore } from '@features/chart/store/chart-store';
import type {
  DrawingObject,
  DrawingPoint,
  DrawingMetadata,
  MeasureMetadata,
  EmojiMetadata,
  ImageMetadata,
} from '@features/chart/types';
import type { PendingDrawing } from '@features/chart/hooks/useDrawingCreation';
import { DRAWING_TOOL_REGISTRY } from '@features/chart/registries/drawing-tools';
import { CHART_TEST_IDS } from '@features/chart/utils/test-ids';

// âââ Props ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

type MainSeriesType = 'Candlestick' | 'Bar' | 'Line' | 'Area' | 'Baseline';

export interface DrawingOverlayProps {
  /** The lightweight-charts IChartApi instance */
  chartApi: IChartApi | null;
  /** The main series API for price coordinate conversion */
  mainSeries: ISeriesApi<MainSeriesType> | null;
  /** The pending drawing being created (first point placed, waiting for second) */
  pendingDrawing: PendingDrawing | null;
  /** Callback when a text note's content is submitted */
  onTextNoteSubmit: (text: string) => void;
}

// âââ Coordinate conversion ââââââââââââââââââââââââââââââââââââââââââââââââââ

interface PixelPoint {
  x: number;
  y: number;
}

/**
 * Convert chart coordinates (time, price) to pixel coordinates.
 * Returns null if the point is outside the visible range.
 */
function chartToPixel(
  point: DrawingPoint,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
): PixelPoint | null {
  // Convert time to x pixel
  const x = chartApi.timeScale().timeToCoordinate(point.time as never);
  if (x === null) return null;

  // Convert price to y pixel
  const y = mainSeries.priceToCoordinate(point.price);
  if (y === null) return null;

  return { x, y };
}

// âââ Viewport intersection helpers ââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Compute the endpoint of a ray from P1 through P2 extended to the viewport boundary.
 * The ray starts at P1 and goes through P2 and beyond.
 */
function extendRayToViewport(
  p1: PixelPoint,
  p2: PixelPoint,
  containerWidth: number,
  containerHeight: number,
): PixelPoint {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  if (dx === 0 && dy === 0) return p2;

  let tMin = Infinity;
  // Check each viewport boundary; smallest positive t is the first exit
  if (dx > 0) tMin = Math.min(tMin, (containerWidth - p1.x) / dx);
  if (dx < 0) tMin = Math.min(tMin, (0 - p1.x) / dx);
  if (dy > 0) tMin = Math.min(tMin, (containerHeight - p1.y) / dy);
  if (dy < 0) tMin = Math.min(tMin, (0 - p1.y) / dy);
  if (tMin === Infinity) return p2;

  return { x: p1.x + tMin * dx, y: p1.y + tMin * dy };
}

/**
 * Compute both endpoints of a line through P1 and P2 extended to the viewport
 * boundaries in both directions.
 */
function extendLineToViewportBothEnds(
  p1: PixelPoint,
  p2: PixelPoint,
  containerWidth: number,
  containerHeight: number,
): { start: PixelPoint; end: PixelPoint } {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  if (dx === 0 && dy === 0) return { start: p1, end: p2 };

  let tNeg = -Infinity; // largest negative t (backward from P1)
  let tPos = Infinity;  // smallest positive t (forward from P1)

  const considerEdge = (t: number) => {
    if (t < 0) tNeg = Math.max(tNeg, t);
    else tPos = Math.min(tPos, t);
  };

  // Left edge (x = 0)
  if (dx !== 0) considerEdge((0 - p1.x) / dx);
  // Right edge (x = containerWidth)
  if (dx !== 0) considerEdge((containerWidth - p1.x) / dx);
  // Top edge (y = 0)
  if (dy !== 0) considerEdge((0 - p1.y) / dy);
  // Bottom edge (y = containerHeight)
  if (dy !== 0) considerEdge((containerHeight - p1.y) / dy);

  if (tNeg === -Infinity) tNeg = 0;
  if (tPos === Infinity) tPos = 1;

  return {
    start: { x: p1.x + tNeg * dx, y: p1.y + tNeg * dy },
    end: { x: p1.x + tPos * dx, y: p1.y + tPos * dy },
  };
}

/** Convert a lineStyle value to an SVG strokeDasharray, or undefined for solid */
function toDashArray(lineStyle: DrawingObject['style']['lineStyle']): string | undefined {
  return lineStyle === 'dashed' ? '6,4' : lineStyle === 'dotted' ? '2,3' : undefined;
}

// âââ Tool classification helpers ââââââââââââââââââââââââââââââââââââââââââââ

/** Check if a tool uses freehand placement */
function isFreehandTool(toolType: string): boolean {
  const config = DRAWING_TOOL_REGISTRY.find((t) => t.id === toolType);
  return config?.placementBehavior === 'freehand';
}

/** Check if a tool uses drag placement */
function isDragTool(toolType: string): boolean {
  const config = DRAWING_TOOL_REGISTRY.find((t) => t.id === toolType);
  return config?.placementBehavior === 'drag';
}

// âââ Component ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export function DrawingOverlay({
  chartApi,
  mainSeries,
  pendingDrawing,
  onTextNoteSubmit,
}: DrawingOverlayProps) {
  const drawings = useChartStore((s) => s.drawings);
  const selectedDrawingId = useChartStore((s) => s.selectedDrawingId);
  const svgRef = useRef<SVGSVGElement>(null);
  const [renderTick, setRenderTick] = useState(0);
  const [textInputState, setTextInputState] = useState<{
    x: number;
    y: number;
    visible: boolean;
  }>({ x: 0, y: 0, visible: false });

  // Suppress unused variable warning â renderTick drives re-renders
  void renderTick;

  // ââ Re-render on visible range changes âââââââââââââââââââââââââââââââââââââ
  // When the user zooms/pans, pixel positions of drawings change.
  // We subscribe to the visible time range change event to trigger re-render.

  const forceRerender = useCallback(() => {
    setRenderTick((t) => t + 1);
  }, []);

  useEffect(() => {
    if (!chartApi) return;

    const handler = () => {
      forceRerender();
    };

    chartApi.timeScale().subscribeVisibleTimeRangeChange(handler);

    return () => {
      chartApi.timeScale().unsubscribeVisibleTimeRangeChange(handler);
    };
  }, [chartApi, forceRerender]);

  // ââ Handle pending text note / price_note / callout ââââââââââââââââââââââââ

  useEffect(() => {
    if (
      pendingDrawing &&
      (pendingDrawing.toolType === 'text_note' ||
        pendingDrawing.toolType === 'price_note' ||
        pendingDrawing.toolType === 'callout') &&
      pendingDrawing.points.length === 1 &&
      chartApi &&
      mainSeries
    ) {
      const pixel = chartToPixel(pendingDrawing.points[0]!, chartApi, mainSeries);
      if (pixel) {
        setTextInputState({ x: pixel.x, y: pixel.y, visible: true });
      }
    } else {
      setTextInputState((prev) => prev.visible ? { x: 0, y: 0, visible: false } : prev);
    }
  }, [pendingDrawing, chartApi, mainSeries]);

  // ââ Handle text input ââââââââââââââââââââââââââââââââââââââââââââââââââââââ

  const handleTextInputSubmit = useCallback(
    (text: string) => {
      if (text.trim()) {
        onTextNoteSubmit(text.trim());
      }
      setTextInputState({ x: 0, y: 0, visible: false });
    },
    [onTextNoteSubmit],
  );

  const handleTextInputCancel = useCallback(() => {
    setTextInputState({ x: 0, y: 0, visible: false });
  }, []);

  // ââ Guard: no chart API ââââââââââââââââââââââââââââââââââââââââââââââââââââ

  if (!chartApi || !mainSeries) return null;

  // Get container dimensions from the SVG's parent
  const containerWidth = svgRef.current?.parentElement?.clientWidth ?? 0;
  const containerHeight = svgRef.current?.parentElement?.clientHeight ?? 0;

  return (
    <>
      {/* SVG drawing layer */}
      <svg
        ref={svgRef}
        className="drawing-overlay"
        data-testid={CHART_TEST_IDS.drawingLayer}
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
          zIndex: 10,
        }}
        xmlns="http://www.w3.org/2000/svg"
      >
        {/* Render committed drawings */}
        {drawings
          .filter((d) => d.visible)
          .map((drawing) => (
            <DrawingRenderer
              key={drawing.id}
              drawing={drawing}
              chartApi={chartApi}
              mainSeries={mainSeries}
              containerWidth={containerWidth}
              containerHeight={containerHeight}
              isSelected={drawing.id === selectedDrawingId}
            />
          ))}

        {/* Render pending (in-progress) drawing */}
        {pendingDrawing && pendingDrawing.points.length > 0 && (
          <PendingDrawingRenderer
            pending={pendingDrawing}
            chartApi={chartApi}
            mainSeries={mainSeries}
            containerWidth={containerWidth}
            containerHeight={containerHeight}
          />
        )}
      </svg>

      {/* Text input overlay for text notes (DOM element, not SVG) */}
      <TextNoteInput
        x={textInputState.x}
        y={textInputState.y}
        visible={textInputState.visible}
        onSubmit={handleTextInputSubmit}
        onCancel={handleTextInputCancel}
      />
    </>
  );
}

// âââ DrawingRenderer â Renders a single committed drawing âââââââââââââââââââ

interface DrawingRendererProps {
  drawing: DrawingObject;
  chartApi: IChartApi;
  mainSeries: ISeriesApi<MainSeriesType>;
  containerWidth: number;
  containerHeight: number;
  isSelected: boolean;
}

function DrawingRenderer({
  drawing,
  chartApi,
  mainSeries,
  containerWidth,
  containerHeight,
  isSelected,
}: DrawingRendererProps) {
  const { toolType, points, style, text } = drawing;

  if (points.length === 0) return null;

  // When selected, use a brighter color to indicate selection
  const renderStyle = isSelected
    ? { ...style, color: '#4a9eff', lineWidth: style.lineWidth + 1 }
    : style;

  switch (toolType) {
    case 'trend_line':
      return renderTrendLine(points, renderStyle, chartApi, mainSeries);
    case 'horizontal_line':
      return renderHorizontalLine(points, renderStyle, chartApi, mainSeries, containerWidth);
    case 'vertical_line':
      return renderVerticalLine(points, renderStyle, chartApi, mainSeries, containerHeight);
    case 'rectangle':
      return renderRectangle(points, renderStyle, chartApi, mainSeries);
    case 'text_note':
      return renderTextNote(points, renderStyle, text, chartApi, mainSeries);
    case 'measure':
      return renderMeasure(points, renderStyle, drawing.metadata, chartApi, mainSeries);
    // Trend extension tools
    case 'ray_line':
      return renderRayLine(points, renderStyle, chartApi, mainSeries, containerWidth, containerHeight);
    case 'extended_line':
      return renderExtendedLine(points, renderStyle, chartApi, mainSeries, containerWidth, containerHeight);
    case 'arrow_line':
      return renderArrowLine(points, renderStyle, chartApi, mainSeries);
    case 'trend_angle':
      return renderTrendAngle(points, renderStyle, chartApi, mainSeries);
    case 'disjoint_angle':
      return renderDisjointAngle(points, renderStyle, chartApi, mainSeries);
    // Annotation tools
    case 'arrow_up':
      return renderArrowUp(points, renderStyle, chartApi, mainSeries);
    case 'arrow_down':
      return renderArrowDown(points, renderStyle, chartApi, mainSeries);
    case 'flag':
      return renderFlag(points, renderStyle, chartApi, mainSeries);
    case 'price_label':
      return renderPriceLabel(points, renderStyle, text, chartApi, mainSeries);
    case 'price_note':
      return renderPriceNote(points, renderStyle, text, chartApi, mainSeries);
    case 'arrow_marker':
      return renderArrowMarker(points, renderStyle, chartApi, mainSeries);
    case 'callout':
      return renderCallout(points, renderStyle, text, drawing, chartApi, mainSeries);
    // Icon / media tools
    case 'emoji_icon':
      return renderEmojiIcon(drawing, renderStyle, chartApi, mainSeries);
    case 'image_embed':
      return renderImageEmbed(drawing, renderStyle, chartApi, mainSeries);
    default:
      return null;
  }
}

// âââ PendingDrawingRenderer â Renders the in-progress drawing âââââââââââââââ

interface PendingDrawingRendererProps {
  pending: PendingDrawing;
  chartApi: IChartApi;
  mainSeries: ISeriesApi<MainSeriesType>;
  containerWidth: number;
  containerHeight: number;
}

function PendingDrawingRenderer({
  pending,
  chartApi,
  mainSeries,
  containerWidth,
  containerHeight,
}: PendingDrawingRendererProps) {
  const { toolType, points, isDragging } = pending;

  if (points.length === 0) return null;

  const style = {
    color: '#2962ff',
    lineWidth: 1,
    lineStyle: 'dashed' as const,
    fill: 'rgba(41, 98, 255, 0.05)',
  };

  // ââ Freehand (brush / highlighter / scribble) ââââââââââââââââââââââââââââ
  // Render the in-progress path as a polyline connecting all sampled points
  if (isDragging && points.length >= 2 && isFreehandTool(toolType)) {
    return renderFreehandPath(points, style, chartApi, mainSeries);
  }

  // ââ Drag-based tools (rectangle, ellipse, circle, range tools, measure) ââ
  // During drag, render the preview shape between P1 and current mouse pos
  if (isDragging && points.length >= 2 && isDragTool(toolType)) {
    return renderDragPreview(toolType, points, style, chartApi, mainSeries, containerWidth, containerHeight);
  }

  switch (toolType) {
    case 'trend_line': {
      if (points.length === 1) {
        // Show a dot at the first point
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return (
          <circle
            cx={pixel.x}
            cy={pixel.y}
            r={3}
            fill={style.color}
            opacity={0.7}
          />
        );
      }
      return renderTrendLine(points, style, chartApi, mainSeries);
    }
    case 'rectangle': {
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return (
          <circle
            cx={pixel.x}
            cy={pixel.y}
            r={3}
            fill={style.color}
            opacity={0.7}
          />
        );
      }
      return renderRectangle(points, style, chartApi, mainSeries);
    }
    case 'text_note':
    case 'price_note': {
      // Show a dot at the click point while waiting for text input
      const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
      if (!pixel) return null;
      return (
        <circle
          cx={pixel.x}
          cy={pixel.y}
          r={3}
          fill={style.color}
          opacity={0.7}
        />
      );
    }
    case 'ray_line': {
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return <circle cx={pixel.x} cy={pixel.y} r={3} fill={style.color} opacity={0.7} />;
      }
      return renderRayLine(points, style, chartApi, mainSeries, containerWidth, containerHeight);
    }
    case 'extended_line': {
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return <circle cx={pixel.x} cy={pixel.y} r={3} fill={style.color} opacity={0.7} />;
      }
      return renderExtendedLine(points, style, chartApi, mainSeries, containerWidth, containerHeight);
    }
    case 'arrow_line': {
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return <circle cx={pixel.x} cy={pixel.y} r={3} fill={style.color} opacity={0.7} />;
      }
      return renderArrowLine(points, style, chartApi, mainSeries);
    }
    case 'trend_angle': {
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return <circle cx={pixel.x} cy={pixel.y} r={3} fill={style.color} opacity={0.7} />;
      }
      return renderTrendAngle(points, style, chartApi, mainSeries);
    }
    case 'callout': {
      // Callout: show dot at first point (text position), and if 2 points exist show leader line
      if (points.length === 1) {
        const pixel = chartToPixel(points[0]!, chartApi, mainSeries);
        if (!pixel) return null;
        return (
          <circle
            cx={pixel.x}
            cy={pixel.y}
            r={3}
            fill={style.color}
            opacity={0.7}
          />
        );
      }
      if (points.length >= 2) {
        const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
        const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
        if (!p1 || !p2) return null;
        return (
          <g>
            <line
              x1={p1.x}
              y1={p1.y}
              x2={p2.x}
              y2={p2.y}
              stroke={style.color}
              strokeWidth={1}
              strokeDasharray="4,3"
            />
            <circle cx={p1.x} cy={p1.y} r={3} fill={style.color} opacity={0.7} />
            <circle cx={p2.x} cy={p2.y} r={3} fill={style.color} opacity={0.7} />
          </g>
        );
      }
      return null;
    }
    default: {
      // Multi-point tools: show dots at placed points + a dashed polyline
      // connecting them so the user sees their progress
      if (points.length >= 1) {
        return renderMultiPointPreview(points, style, chartApi, mainSeries);
      }
      return null;
    }
  }
}

// âââ Individual drawing renderers âââââââââââââââââââââââââââââââââââââââââââ

function renderTrendLine(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const dashArray = style.lineStyle === 'dashed'
    ? '6,4'
    : style.lineStyle === 'dotted'
      ? '2,3'
      : undefined;

  return (
    <line
      x1={p1.x}
      y1={p1.y}
      x2={p2.x}
      y2={p2.y}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      strokeDasharray={dashArray}
    />
  );
}

function renderHorizontalLine(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  containerWidth: number,
) {
  if (points.length < 1) return null;

  const p = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p) return null;

  const dashArray = style.lineStyle === 'dashed'
    ? '6,4'
    : style.lineStyle === 'dotted'
      ? '2,3'
      : undefined;

  return (
    <line
      x1={0}
      y1={p.y}
      x2={containerWidth || 2000}
      y2={p.y}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      strokeDasharray={dashArray}
    />
  );
}

function renderVerticalLine(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  containerHeight: number,
) {
  if (points.length < 1) return null;

  const p = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p) return null;

  const dashArray = style.lineStyle === 'dashed'
    ? '6,4'
    : style.lineStyle === 'dotted'
      ? '2,3'
      : undefined;

  return (
    <line
      x1={p.x}
      y1={0}
      x2={p.x}
      y2={containerHeight || 2000}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      strokeDasharray={dashArray}
    />
  );
}

function renderRectangle(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  const dashArray = style.lineStyle === 'dashed'
    ? '6,4'
    : style.lineStyle === 'dotted'
      ? '2,3'
      : undefined;

  return (
    <rect
      x={x}
      y={y}
      width={width}
      height={height}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      strokeDasharray={dashArray}
      fill={style.fill ?? 'none'}
    />
  );
}

function renderTextNote(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  text: string,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 1 || !text) return null;

  const p = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p) return null;

  return (
    <text
      x={p.x + 6}
      y={p.y - 6}
      fill={style.color}
      fontSize={style.fontSize ?? 14}
      fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
    >
      {text}
    </text>
  );
}

