function renderArrowLine(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return null;

  // Unit direction and perpendicular
  const ux = dx / len;
  const uy = dy / len;
  const px = -uy;
  const py = ux;

  // Arrowhead triangle (8px long, Â±3.2px wide)
  const arrowLen = 8;
  const arrowW = arrowLen * 0.4;
  const tip = p2;
  const base1 = { x: p2.x - ux * arrowLen + px * arrowW, y: p2.y - uy * arrowLen + py * arrowW };
  const base2 = { x: p2.x - ux * arrowLen - px * arrowW, y: p2.y - uy * arrowLen - py * arrowW };

  return (
    <g>
      <line
        x1={p1.x}
        y1={p1.y}
        x2={p2.x - ux * arrowLen * 0.5}
        y2={p2.y - uy * arrowLen * 0.5}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={toDashArray(style.lineStyle)}
      />
      <polygon
        points={`${tip.x},${tip.y} ${base1.x},${base1.y} ${base2.x},${base2.y}`}
        fill={style.color}
        stroke={style.color}
        strokeWidth={1}
      />
    </g>
  );
}

function renderTrendAngle(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;

  // SVG angle from positive x-axis (y-down coordinate system)
  const svgAngle = Math.atan2(dy, dx);
  // Display angle: negate y for math convention (positive = upward from horizontal)
  const displayAngleDeg = Math.round(-svgAngle * 180 / Math.PI);

  // Arc at P1, 20px radius, from horizontal to line direction
  const arcRadius = 20;
  const arcStartX = p1.x + arcRadius;
  const arcStartY = p1.y;
  const arcEndX = p1.x + arcRadius * Math.cos(svgAngle);
  const arcEndY = p1.y + arcRadius * Math.sin(svgAngle);

  // Sweep: clockwise (1) if svgAngle > 0, counterclockwise (0) if < 0
  const sweepFlag = svgAngle >= 0 ? 1 : 0;
  const largeArcFlag = Math.abs(svgAngle) > Math.PI ? 1 : 0;

  const arcPath = `M ${arcStartX} ${arcStartY} A ${arcRadius} ${arcRadius} 0 ${largeArcFlag} ${sweepFlag} ${arcEndX} ${arcEndY}`;

  return (
    <g>
      <line
        x1={p1.x}
        y1={p1.y}
        x2={p2.x}
        y2={p2.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={toDashArray(style.lineStyle)}
      />
      <path
        d={arcPath}
        stroke={style.color}
        strokeWidth={1}
        fill="none"
        opacity={0.7}
      />
      <text
        x={arcEndX + 4}
        y={arcEndY - 4}
        fill={style.color}
        fontSize={11}
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {`${displayAngleDeg}Â°`}
      </text>
    </g>
  );
}

function renderDisjointAngle(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 3) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  const p3 = chartToPixel(points[2]!, chartApi, mainSeries);
  if (!p1 || !p2 || !p3) return null;

  // Vectors from P2 toward P1 and P3
  const v1x = p1.x - p2.x;
  const v1y = p1.y - p2.y;
  const v2x = p3.x - p2.x;
  const v2y = p3.y - p2.y;

  // Angle between the two segments
  const dot = v1x * v2x + v1y * v2y;
  const mag1 = Math.sqrt(v1x * v1x + v1y * v1y);
  const mag2 = Math.sqrt(v2x * v2x + v2y * v2y);
  if (mag1 === 0 || mag2 === 0) return null;

  const cosAngle = Math.max(-1, Math.min(1, dot / (mag1 * mag2)));
  const angleDeg = Math.round(Math.acos(cosAngle) * 180 / Math.PI);

  // Arc at P2 between the two segments
  const arcRadius = 20;
  const angle1 = Math.atan2(v1y, v1x); // direction from P2 toward P1
  const angle2 = Math.atan2(v2y, v2x); // direction from P2 toward P3

  const arcStartX = p2.x + arcRadius * Math.cos(angle1);
  const arcStartY = p2.y + arcRadius * Math.sin(angle1);
  const arcEndX = p2.x + arcRadius * Math.cos(angle2);
  const arcEndY = p2.y + arcRadius * Math.sin(angle2);

  // Shortest arc between the two directions
  let diff = angle2 - angle1;
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;
  const sweepFlag = diff >= 0 ? 1 : 0;
  const largeArcFlag = Math.abs(diff) > Math.PI ? 1 : 0;

  const arcPath = `M ${arcStartX} ${arcStartY} A ${arcRadius} ${arcRadius} 0 ${largeArcFlag} ${sweepFlag} ${arcEndX} ${arcEndY}`;

  // Label position: midpoint of the arc, offset outward
  const midAngle = angle1 + diff / 2;
  const textRadius = arcRadius + 14;
  const textX = p2.x + textRadius * Math.cos(midAngle);
  const textY = p2.y + textRadius * Math.sin(midAngle);

  return (
    <g>
      <line
        x1={p1.x}
        y1={p1.y}
        x2={p2.x}
        y2={p2.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={toDashArray(style.lineStyle)}
      />
      <line
        x1={p2.x}
        y1={p2.y}
        x2={p3.x}
        y2={p3.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={toDashArray(style.lineStyle)}
      />
      <path
        d={arcPath}
        stroke={style.color}
        strokeWidth={1}
        fill="none"
        opacity={0.7}
      />
      <text
        x={textX}
        y={textY}
        fill={style.color}
        fontSize={11}
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {`${angleDeg}Â°`}
      </text>
    </g>
  );
}

// âââ Pitchfork renderers ââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Render a pitchfork drawing (Andrews, Schiff, or Modified Schiff).
 *
 * All three variants draw 3 lines:
 * 1. Median line â origin depends on variant
 * 2. Upper parallel line â through P2, parallel to median
 * 3. Lower parallel line â through P3, parallel to median
 *
 * Variant differences:
 * - andrews_pitchfork: median from P1 â midpoint(P2, P3)
 * - schiff_pitchfork: median from midpoint(P2, P3) â extended in direction P1âmidpoint
 * - modified_schiff_pitchfork: median from midpoint(P1, P2) in time â midpoint(P2, P3)
 *
 * All three extend the median and parallel lines to the viewport edge.
 */
function renderPitchfork(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  metadata: DrawingMetadata | undefined,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  containerWidth: number,
  containerHeight: number,
) {
  if (points.length < 3) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  const p3 = chartToPixel(points[2]!, chartApi, mainSeries);
  if (!p1 || !p2 || !p3) return null;

  const gannMeta = metadata as GannMetadata | undefined;
  const variant = gannMeta?.variant ?? 'andrews';

  // Midpoint of P2 and P3
  const midP2P3: PixelPoint = {
    x: (p2.x + p3.x) / 2,
    y: (p2.y + p3.y) / 2,
  };

  // Determine median line origin and direction based on variant
  let medianStart: PixelPoint;
  let medianDir: PixelPoint; // direction vector of the median line

  if (variant === 'andrews') {
    // Median from P1 through midpoint(P2, P3)
    medianStart = p1;
    medianDir = { x: midP2P3.x - p1.x, y: midP2P3.y - p1.y };
  } else if (variant === 'schiff') {
    // Median from midpoint(P2, P3) in the direction of P1âmidpoint
    medianStart = midP2P3;
    medianDir = { x: midP2P3.x - p1.x, y: midP2P3.y - p1.y };
  } else {
    // modified_schiff: median from midpoint(P1, P2) in TIME dimension
    // In pixel space, "midpoint in time" = average of x coordinates of P1 and P2,
    // but price (y) stays at the midpoint of P2 and P3
    const modifiedOrigin: PixelPoint = {
      x: (p1.x + p2.x) / 2,
      y: midP2P3.y,
    };
    medianStart = modifiedOrigin;
    medianDir = { x: midP2P3.x - modifiedOrigin.x, y: midP2P3.y - modifiedOrigin.y };
  }

  // Normalize median direction
  const medianLen = Math.sqrt(medianDir.x * medianDir.x + medianDir.y * medianDir.y);
  if (medianLen === 0) return null;
  const unitDir: PixelPoint = {
    x: medianDir.x / medianLen,
    y: medianDir.y / medianLen,
  };

  // Perpendicular direction (for parallel offset)
  const perpDir: PixelPoint = {
    x: -unitDir.y,
    y: unitDir.x,
  };

  // Distance from P2 and P3 to the median line (signed, along perpendicular)
  // The median line passes through midP2P3, so:
  // P2 is offset from midP2P3 by (p2 - midP2P3)
  // Project that offset onto perpendicular to get signed distance
  const offsetP2 = (p2.x - midP2P3.x) * perpDir.x + (p2.y - midP2P3.y) * perpDir.y;
  const offsetP3 = (p3.x - midP2P3.x) * perpDir.x + (p3.y - midP2P3.y) * perpDir.y;

  // Extend median line to viewport boundaries
  // We extend from medianStart in the medianDir direction (forward only, like a ray)
  const medianEnd = extendRayToViewport(
    medianStart,
    { x: medianStart.x + medianDir.x, y: medianStart.y + medianDir.y },
    containerWidth,
    containerHeight,
  );

  // Upper parallel: offset by offsetP2 along perpendicular from the median
  const upperStart: PixelPoint = {
    x: medianStart.x + perpDir.x * offsetP2,
    y: medianStart.y + perpDir.y * offsetP2,
  };
  const upperEnd: PixelPoint = {
    x: medianEnd.x + perpDir.x * offsetP2,
    y: medianEnd.y + perpDir.y * offsetP2,
  };

  // Lower parallel: offset by offsetP3 along perpendicular from the median
  const lowerStart: PixelPoint = {
    x: medianStart.x + perpDir.x * offsetP3,
    y: medianStart.y + perpDir.y * offsetP3,
  };
  const lowerEnd: PixelPoint = {
    x: medianEnd.x + perpDir.x * offsetP3,
    y: medianEnd.y + perpDir.y * offsetP3,
  };

  const dashArray = toDashArray(style.lineStyle);

  return (
    <g>
      {/* Median line */}
      <line
        x1={medianStart.x}
        y1={medianStart.y}
        x2={medianEnd.x}
        y2={medianEnd.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
      {/* Upper parallel line (through P2) */}
      <line
        x1={upperStart.x}
        y1={upperStart.y}
        x2={upperEnd.x}
        y2={upperEnd.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
      {/* Lower parallel line (through P3) */}
      <line
        x1={lowerStart.x}
        y1={lowerStart.y}
        x2={lowerEnd.x}
        y2={lowerEnd.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
      {/* Small dots at the 3 anchor points */}
      <circle cx={p1.x} cy={p1.y} r={2} fill={style.color} opacity={0.6} />
      <circle cx={p2.x} cy={p2.y} r={2} fill={style.color} opacity={0.6} />
      <circle cx={p3.x} cy={p3.y} r={2} fill={style.color} opacity={0.6} />
    </g>
  );
}

