function renderImageEmbed(
  drawing: DrawingObject,
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (drawing.points.length < 1) return null;

  const p = chartToPixel(drawing.points[0]!, chartApi, mainSeries);
  if (!p) return null;

  const metadata = drawing.metadata as ImageMetadata | undefined;
  const url = metadata?.url ?? '';
  const w = metadata?.w ?? 64;
  const h = metadata?.h ?? 64;
  const isValidUrl = url.startsWith('https://') || url.startsWith('data:image/');

  if (isValidUrl) {
    return (
      <image
        href={url}
        x={p.x - w / 2}
        y={p.y - h / 2}
        width={w}
        height={h}
        opacity={style.opacity ?? 1}
      />
    );
  }

  // Invalid or missing URL: placeholder rect + alt text
  return (
    <g>
      <rect
        x={p.x - w / 2}
        y={p.y - h / 2}
        width={w}
        height={h}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="4,3"
        fill="rgba(120, 123, 134, 0.1)"
      />
      <text
        x={p.x}
        y={p.y}
        fill={style.color}
        fontSize={10}
        textAnchor="middle"
        dominantBaseline="central"
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {url ? 'Invalid URL' : 'No image'}
      </text>
    </g>
  );
}

// âââ Pending drawing renderers ââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Render a freehand brush path as an SVG <path> connecting all sampled points.
 * Used for brush / highlighter / scribble during and after stroke.
 */
function renderFreehandPath(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length < 2) return null;

  const d = pixels
    .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
    .join(' ');

  return (
    <path
      d={d}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={style.opacity ?? 1}
    />
  );
}

/**
 * Render a drag preview based on the tool type.
 * During drag, shows the shape between P1 and the current mouse position.
 */
function renderDragPreview(
  toolType: string,
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  _containerWidth: number,
  _containerHeight: number,
) {
  // Range/measure tools: dashed rectangle preview
  if (
    toolType === 'range_tool' ||
    toolType === 'date_range' ||
    toolType === 'price_range'
  ) {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Measure: dashed rectangle with live delta values
  if (toolType === 'measure') {
    return renderMeasure(points, style, undefined, chartApi, mainSeries);
  }

  // Rectangle: standard rectangle preview
  if (toolType === 'rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Ellipse/circle/rounded_rectangle: rectangle bounding box as placeholder
  if (toolType === 'ellipse' || toolType === 'circle' || toolType === 'rounded_rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Generic drag fallback: show rectangle
  return renderRectangle(points, style, chartApi, mainSeries);
}

/**
 * Render a multi-point tool preview: dots at each placed point + dashed
 * polyline connecting them, so the user sees their progress while placing
 * additional points.
 */
function renderMultiPointPreview(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length === 0) return null;

  const elements: React.ReactNode[] = [];

  // Dots at each point
  for (const p of pixels) {
    elements.push(
      <circle
        key={`dot-${p.x}-${p.y}`}
        cx={p.x}
        cy={p.y}
        r={3}
        fill={style.color}
        opacity={0.7}
      />,
    );
  }

  // Dashed polyline connecting placed points
  if (pixels.length >= 2) {
    const d = pixels
      .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
      .join(' ');
    elements.push(
      <path
        key="polyline"
        d={d}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="6,4"
        fill="none"
        opacity={0.7}
      />,
    );
  }

  return <g>{elements}</g>;
}

// âââ TextNoteInput â DOM overlay for text input on the chart ââââââââââââââââ

interface TextNoteInputProps {
  x: number;
  y: number;
  visible: boolean;
  onSubmit: (text: string) => void;
  onCancel: () => void;
}

function TextNoteInput({ x, y, visible, onSubmit, onCancel }: TextNoteInputProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (visible && inputRef.current) {
      inputRef.current.focus();
    }
  }, [visible]);

  if (!visible) return null;

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      const text = (event.target as HTMLInputElement).value.trim();
      if (text) {
        onSubmit(text);
      } else {
        onCancel();
      }
    } else if (event.key === 'Escape') {
      onCancel();
    }
  };

  const handleBlur = (event: React.FocusEvent<HTMLInputElement>) => {
    const text = event.target.value.trim();
    if (text) {
      onSubmit(text);
    } else {
      onCancel();
    }
  };

  return (
    <input
      ref={inputRef}
      type="text"
      className="drawing-overlay__text-input"
      data-testid="drawing-text-note-input"
      style={{
        position: 'absolute',
        left: x + 6,
        top: y - 14,
        zIndex: 20,
        pointerEvents: 'auto',
        background: 'rgba(19, 23, 34, 0.9)',
        border: '1px solid #2962ff',
        color: '#d1d4dc',
        fontSize: 14,
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif",
        padding: '2px 6px',
        borderRadius: 2,
        outline: 'none',
        minWidth: 120,
      }}
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
      aria-label="Enter text note"
      placeholder="Type text..."
    />
  );
}

