/**
 * useDrawingCreation â Hook that handles drawing creation interaction on the chart.
 *
 * Refactored into 5 distinct interaction model state machines:
 * 1. handleSingleClick  â single-point tools (horizontal_line, vertical_line,
 *                         annotations, icons) â one click commits the drawing
 * 2. handleTwoClick     â two-point tools (trend_line, ray_line, rectangle,
 *                         fibonacci, gann, shapes, positions, etc.) â two clicks
 * 3. handleMultiPoint   â multi-point tools (pitchfork, patterns, triangle_shape,
 *                         parallelogram, disjoint_angle) â N clicks, with Enter/
 *                         double-click early completion
 * 4. handleDrag         â drag-based tools (range_tool, date_range, price_range,
 *                         measure, rectangle, ellipse, circle, rounded_rectangle)
 *                         â mousedown â mousemove (live preview) â mouseup commit
 * 5. handleFreehand     â freehand brush tools (brush, highlighter, scribble)
 *                         â mousedown â mousemove (throttled 16ms sampling) â
 *                           mouseup commit
 *
 * The flat switch from the original implementation is replaced by a dispatch
 * function that routes to the appropriate handler based on the tool's
 * placementBehavior from DRAWING_TOOL_REGISTRY.
 *
 * Cursor and crosshair tools deactivate drawing mode.
 *
 * Drawings are added to the store via addDrawing() which pushes undo history,
 * and optionally persisted to the API.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import type { IChartApi, ISeriesApi } from 'lightweight-charts';
import { useChartStore } from '@features/chart/store/chart-store';
import { chartApi } from '@features/chart/api';
import {
  DRAWING_TOOL_REGISTRY,
} from '@features/chart/registries/drawing-tools';
import type {
  DrawingTool,
  DrawingObject,
  DrawingPoint,
  DrawingStyle,
  DrawingMetadata,
} from '@features/chart/types';

// âââ Multi-point tool specs âââââââââââââââââââââââââââââââââââââââââââââââââ
//
// Defines expected/min points for multi-point tools. The registry's
// pointsModel field identifies which tools are multi-point; this table
// provides the exact counts and minimum-commit thresholds.

export interface MultiPointSpec {
  /** Exact number of points that auto-commits the drawing */
  points: number;
  /** Minimum points required for early (Enter / dblclick) commit */
  minPoints: number;
}

export const MULTI_POINT_SPECS: Record<string, MultiPointSpec> = {
  // Trend (disjoint_angle is 3 points per PRD Â§3.5)
  disjoint_angle: { points: 3, minPoints: 3 },
  // Channels (parallel_channel and asc/desc/flat are 3 points per PRD Â§3.16-3.19)
  parallel_channel: { points: 3, minPoints: 3 },
  ascending_channel: { points: 3, minPoints: 3 },
  descending_channel: { points: 3, minPoints: 3 },
  flat_channel: { points: 3, minPoints: 3 },
  // Pitchfork (3 points per PRD Â§3.21)
  andrews_pitchfork: { points: 3, minPoints: 3 },
  schiff_pitchfork: { points: 3, minPoints: 3 },
  modified_schiff_pitchfork: { points: 3, minPoints: 3 },
  // Patterns (per PRD Â§3 Phase 3)
  elliott_impulse_wave: { points: 6, minPoints: 5 },
  elliott_corrective_wave: { points: 4, minPoints: 3 },
  elliott_triangle: { points: 6, minPoints: 5 },
  elliott_combo: { points: 4, minPoints: 3 },
  head_and_shoulders: { points: 7, minPoints: 5 },
