/** Arrow marker â 12px arrow triangle */
function renderArrowMarker(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 1) return null;
  const p = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p) return null;

  // 12px triangle pointing up by default
  const markerPoints = `${p.x},${p.y - 6} ${p.x - 5},${p.y + 4} ${p.x + 5},${p.y + 4}`;
  return (
    <polygon
      points={markerPoints}
      fill={style.color}
      stroke={style.color}
