/** Callout â text note with leader line to anchor point */
function renderCallout(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  text: string,
  drawing: DrawingObject,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 1) return null;
  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  if (!p1) return null;

  const elements: React.ReactNode[] = [];

  // Leader line to anchor (P2 or metadata anchor)
  if (points.length >= 2) {
    const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
          y1={p1.y}
          x2={p2.x}
          y2={p2.y}
          stroke={style.color}
          strokeWidth={1}
          strokeDasharray="4,3"
        />,
      );
      // Small dot at the anchor point
      elements.push(
        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  } else if (drawing.metadata?.kind === 'callout') {
    const anchor = drawing.metadata.anchor;
    const p2 = chartToPixel(anchor, chartApi, mainSeries);
    if (p2) {
      elements.push(
        <line
          key="leader"
          x1={p1.x}
          y1={p1.y}
          x2={p2.x}
          y2={p2.y}
          stroke={style.color}
          strokeWidth={1}
          strokeDasharray="4,3"
        />,
      );
      elements.push(
        <circle
          key="anchor-dot"
          cx={p2.x}
          cy={p2.y}
          r={2}
          fill={style.color}
        />,
      );
    }
  }

  // Text at P1
  if (text) {
    const fontSize = style.fontSize ?? 14;
    elements.push(
      <text
        key="callout-text"
        x={p1.x + 6}
        y={p1.y - 6}
        fill={style.color}
        fontSize={fontSize}
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {text}
      </text>,
    );
  }

  return elements.length > 0 ? <g>{elements}</g> : null;
}

// âââ Measure tool helpers âââââââââââââââââââââââââââââââââââââââââââââââââââ
function computeMeasureValues(p1: DrawingPoint, p2: DrawingPoint): {
  deltaPrice: number;
  deltaPrct: number;
  deltaBars: number;
} {
  const deltaPrice = p2.price - p1.price;
  const deltaPrct = p1.price !== 0 ? (deltaPrice / Math.abs(p1.price)) * 100 : 0;
  // Bars are the time difference in chart time units. Each bar = 1 unit in
  // most lightweight-charts configurations, so we use the absolute time diff.
  const deltaBars = Math.abs(Math.round(p2.time - p1.time));
  return { deltaPrice, deltaPrct, deltaBars };
}

/**
 * Format a price delta with sign and decimal places.
 */
function formatDeltaPrice(value: number): string {
  const sign = value >= 0 ? '+' : '';
  return `${sign}${value.toFixed(2)}`;
}

/**
 * Format a percentage delta with sign.
 */
function formatDeltaPrct(value: number): string {
  const sign = value >= 0 ? '+' : '';
  return `${sign}${value.toFixed(2)}%`;
}

/**
 * Render the measure tool: dashed rectangle between P1 and P2, with a
 * centered text block showing Îprice, Îprice%, and Îbars.
 * If metadata is available, uses pre-computed values; otherwise computes
 * from points directly (so preview during drag also works).
 */
function renderMeasure(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  metadata: DrawingMetadata | undefined,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  // Use metadata if available (committed drawing), otherwise compute (preview)
  const measureMeta = metadata as MeasureMetadata | undefined;
  const computed = computeMeasureValues(points[0]!, points[1]!);
  const deltaPrice = measureMeta?.deltaPrice ?? computed.deltaPrice;
  const deltaPrct = measureMeta?.deltaPrct ?? computed.deltaPrct;
  const deltaBars = measureMeta?.deltaBars ?? computed.deltaBars;

  // Center text position
  const cx = x + width / 2;
  const cy = y + height / 2;

  const fontFamily = "-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif";

  return (
    <g>
      {/* Dashed rectangle */}
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="6,4"
        fill={style.fill ?? 'rgba(120, 123, 134, 0.05)'}
      />
      {/* Delta values text block â centered in rectangle */}
      <text
        x={cx}
        y={cy - 14}
        fill={style.color}
        fontSize={12}
        fontFamily={fontFamily}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {formatDeltaPrice(deltaPrice)} ({formatDeltaPrct(deltaPrct)})
      </text>
      <text
        x={cx}
        y={cy + 4}
        fill={style.color}
        fontSize={12}
        fontFamily={fontFamily}
        textAnchor="middle"
        dominantBaseline="middle"
      >
        {deltaBars} bars
      </text>
    </g>
  );
}

