// âââ Gann tool renderers ââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/** Default Gann fan slope ratios */
const GANN_FAN_RATIOS = [1/8, 1/4, 1/3, 1/2, 1, 2, 3, 4, 8];

/**
 * Gann Fan: 9 rays from P1, each at a slope = ratio Ã price-per-bar,
 * extending to the viewport boundaries.
 * P1 is the origin; P2 determines the price-per-bar unit.
 */
function renderGannFan(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  metadata: DrawingMetadata | undefined,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  containerWidth: number,
  containerHeight: number,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  // Price per bar: how much price changes per unit of time, from the two points
  const dtTime = points[1]!.time - points[0]!.time;
  const dPrice = points[1]!.price - points[0]!.price;
  if (dtTime === 0) return null;
  const pricePerBar = dPrice / dtTime;

  // Use metadata ratios if available, otherwise defaults
  const gannMeta = metadata as GannMetadata | undefined;
  const ratios = gannMeta?.ratios ?? GANN_FAN_RATIOS;

  const elements: React.ReactNode[] = [];

  // Draw the 1Ã1 line (main trend line from P1 through P2)
  const mainEnd = extendRayToViewport(p1, p2, containerWidth, containerHeight);
  elements.push(
    <line
      key="gann-1x1"
      x1={p1.x}
      y1={p1.y}
      x2={mainEnd.x}
      y2={mainEnd.y}
      stroke={style.color}
      strokeWidth={style.lineWidth + 1}
    />,
  );

  // Draw each ratio ray from P1
  for (let i = 0; i < ratios.length; i++) {
    const ratio = ratios[i]!;
    if (ratio === 1) continue; // Already drawn as the main line

    // Each ray's slope in price/time = ratio Ã pricePerBar
    // In pixel space: dx = dt * pixelsPerBar, dy = -slope * dt * pixelsPerPriceUnit
    // We compute the direction in pixel space from P1 toward a virtual P2 at the
    // ratio's slope. Use a large time offset to get a direction vector, then extend.
    const virtualDx = p2.x - p1.x; // pixel distance for the time span
    const slope = ratio * pricePerBar;
    // dy in pixels: (slope * dtTime) converted via priceToCoordinate delta
    // Approximate: scale by the same pixel ratio as the 1Ã1 line
    const oneToOneSlope = pricePerBar; // 1Ã1 slope
    const oneToOneDy = p2.y - p1.y; // pixel delta for the 1Ã1
    const scale = oneToOneSlope !== 0 ? oneToOneDy / oneToOneSlope : 0;
    const virtualDy = slope * scale;

    // Direction vector from P1
    const dirX = virtualDx;
    const dirY = virtualDy;

    if (dirX === 0 && dirY === 0) continue;

    const endpoint = extendRayToViewport(
      p1,
      { x: p1.x + dirX, y: p1.y + dirY },
      containerWidth,
      containerHeight,
    );

    // Distinguish above/below 1Ã1 with different dash patterns
    const dashArray = ratio < 1 ? '4,4' : ratio > 1 ? '2,3' : undefined;

    elements.push(
      <line
        key={`gann-ray-${ratio}`}
        x1={p1.x}
        y1={p1.y}
        x2={endpoint.x}
        y2={endpoint.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
        opacity={0.6}
      />,
    );

    // Label at the endpoint
    const labelText = ratio < 1
      ? `1Ã${Math.round(1 / ratio)}`
      : `${ratio}Ã1`;
    elements.push(
      <text
        key={`gann-label-${ratio}`}
        x={endpoint.x + 4}
        y={endpoint.y - 4}
        fill={style.color}
        fontSize={9}
        opacity={0.7}
        fontFamily="-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif"
      >
        {labelText}
      </text>,
    );
  }

  return <g>{elements}</g>;
}

/**
 * Gann Box: rectangle defined by P1âP2 + internal 4Ã4 grid.
 */
function renderGannBox(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  if (width === 0 && height === 0) return null;

  const elements: React.ReactNode[] = [];
  const gridDivisions = 4;

  // Outer rectangle
  elements.push(
    <rect
      key="gann-box-outer"
      x={x}
      y={y}
      width={width}
      height={height}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill={style.fill ?? 'none'}
    />,
  );

  // Internal horizontal grid lines
  for (let i = 1; i < gridDivisions; i++) {
    const gy = y + (height * i) / gridDivisions;
    elements.push(
      <line
        key={`gann-box-h-${i}`}
        x1={x}
        y1={gy}
        x2={x + width}
        y2={gy}
        stroke={style.color}
        strokeWidth={style.lineWidth * 0.5}
        opacity={0.4}
      />,
    );
  }

  // Internal vertical grid lines
  for (let i = 1; i < gridDivisions; i++) {
    const gx = x + (width * i) / gridDivisions;
    elements.push(
      <line
        key={`gann-box-v-${i}`}
        x1={gx}
        y1={y}
        x2={gx}
        y2={y + height}
        stroke={style.color}
        strokeWidth={style.lineWidth * 0.5}
        opacity={0.4}
      />,
    );
  }

  return <g>{elements}</g>;
}

/**
 * Gann Square: square with side = max(price range, time range),
 * internal diagonals and midlines.
 */
function renderGannSquare(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  // Side = max dimension so it's always a square
  const side = Math.max(width, height);

  // Compute top-left of the square centered on the bounding box
  const cx = (p1.x + p2.x) / 2;
  const cy = (p1.y + p2.y) / 2;
  const x = cx - side / 2;
  const y = cy - side / 2;

  const elements: React.ReactNode[] = [];

  // Square outline
  elements.push(
    <rect
      key="gann-square-outer"
      x={x}
      y={y}
      width={side}
      height={side}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill={style.fill ?? 'none'}
    />,
  );

  // Diagonals
  elements.push(
    <line
      key="gann-square-diag-1"
      x1={x}
      y1={y}
      x2={x + side}
      y2={y + side}
      stroke={style.color}
      strokeWidth={style.lineWidth * 0.5}
      opacity={0.5}
    />,
  );
  elements.push(
    <line
      key="gann-square-diag-2"
      x1={x + side}
      y1={y}
      x2={x}
      y2={y + side}
      stroke={style.color}
      strokeWidth={style.lineWidth * 0.5}
      opacity={0.5}
    />,
  );

  // Midline (horizontal)
  elements.push(
    <line
      key="gann-square-midline-h"
      x1={x}
      y1={y + side / 2}
      x2={x + side}
      y2={y + side / 2}
      stroke={style.color}
      strokeWidth={style.lineWidth * 0.5}
      opacity={0.5}
    />,
  );

  // Midline (vertical)
  elements.push(
    <line
      key="gann-square-midline-v"
      x1={x + side / 2}
      y1={y}
      x2={x + side / 2}
      y2={y + side}
      stroke={style.color}
      strokeWidth={style.lineWidth * 0.5}
      opacity={0.5}
    />,
  );

  return <g>{elements}</g>;
}

/**
 * Gann Diamond: 45Â° rotated rectangle with vertices at the edge midpoints
 * of the P1âP2 bounding box.
 */
function renderGannDiamond(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const x = Math.min(p1.x, p2.x);
  const y = Math.min(p1.y, p2.y);
  const width = Math.abs(p2.x - p1.x);
  const height = Math.abs(p2.y - p1.y);

  if (width === 0 && height === 0) return null;

  // Diamond vertices = midpoints of the 4 edges of the bounding box
  const top = { x: x + width / 2, y: y };
  const right = { x: x + width, y: y + height / 2 };
  const bottom = { x: x + width / 2, y: y + height };
  const left = { x: x, y: y + height / 2 };

  const diamondPoints = `${top.x},${top.y} ${right.x},${right.y} ${bottom.x},${bottom.y} ${left.x},${left.y}`;

  return (
    <polygon
      points={diamondPoints}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill={style.fill ?? 'none'}
    />
  );
}

// âââ Pending drawing renderers ââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Render a freehand brush path as an SVG <path> connecting all sampled points.
 * Used for brush / highlighter / scribble during and after stroke.
 */
function renderFreehandPath(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;

  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length < 2) return null;

  const d = pixels
    .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
    .join(' ');

  return (
    <path
      d={d}
      stroke={style.color}
      strokeWidth={style.lineWidth}
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={style.opacity ?? 1}
    />
  );
}

/**
 * Render a drag preview based on the tool type.
 * During drag, shows the shape between P1 and the current mouse position.
 */
function renderDragPreview(
  toolType: string,
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
  _containerWidth: number,
  _containerHeight: number,
) {
  // Range/measure tools: dashed rectangle preview
  if (
    toolType === 'range_tool' ||
    toolType === 'date_range' ||
    toolType === 'price_range'
  ) {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Measure: dashed rectangle with live delta values
  if (toolType === 'measure') {
    return renderMeasure(points, style, undefined, chartApi, mainSeries);
  }

  // Rectangle: standard rectangle preview
  if (toolType === 'rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Ellipse/circle/rounded_rectangle: rectangle bounding box as placeholder
  if (toolType === 'ellipse' || toolType === 'circle' || toolType === 'rounded_rectangle') {
    return renderRectangle(points, style, chartApi, mainSeries);
  }

  // Generic drag fallback: show rectangle
  return renderRectangle(points, style, chartApi, mainSeries);
}

/**
 * Render a multi-point tool preview: dots at each placed point + dashed
 * polyline connecting them, so the user sees their progress while placing
 * additional points.
 */
function renderMultiPointPreview(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  const pixels = points
    .map((pt) => chartToPixel(pt, chartApi, mainSeries))
    .filter((p): p is PixelPoint => p !== null);

  if (pixels.length === 0) return null;

  const elements: React.ReactNode[] = [];

  // Dots at each point
  for (const p of pixels) {
    elements.push(
      <circle
        key={`dot-${p.x}-${p.y}`}
        cx={p.x}
        cy={p.y}
        r={3}
        fill={style.color}
        opacity={0.7}
      />,
    );
  }

  // Dashed polyline connecting placed points
  if (pixels.length >= 2) {
    const d = pixels
      .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
      .join(' ');
    elements.push(
      <path
        key="polyline"
        d={d}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray="6,4"
        fill="none"
        opacity={0.7}
      />,
    );
  }

  return <g>{elements}</g>;
}

// âââ Channel renderers ââââââââââââââââââââââââââââââââââââââââââââââââââââââ

/**
 * Compute the perpendicular offset of point P3 from the line P1âP2.
 * Returns the signed distance (positive = P3 is on the left side of P1âP2).
 */
function perpOffset(p1: PixelPoint, p2: PixelPoint, p3: PixelPoint): number {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return 0;
  // Cross product gives signed distance
  return ((p3.x - p1.x) * dy - (p3.y - p1.y) * dx) / len;
}

/**
 * Shift a point by a perpendicular offset from the P1âP2 direction.
 * Positive offset shifts to the left of the P1âP2 direction.
 */
function shiftPerpendicular(p1: PixelPoint, p2: PixelPoint, point: PixelPoint, offset: number): PixelPoint {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len === 0) return point;
  // Unit perpendicular (left-hand normal)
  const nx = -dy / len;
  const ny = dx / len;
  return { x: point.x + nx * offset, y: point.y + ny * offset };
}

/**
 * Render a parallel channel: main line P1âP2 + parallel line through P3.
 * Also used for ascending/descending/flat_channel which are parallel_channel
 * variants with different default colors and direction metadata.
 */
function renderParallelChannel(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  _drawing: DrawingObject,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 3) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  const p3 = chartToPixel(points[2]!, chartApi, mainSeries);
  if (!p1 || !p2 || !p3) return null;

  // Compute perpendicular offset of P3 from the main line
  const offset = perpOffset(p1, p2, p3);

  // Shift P1 and P2 by the offset to create the parallel line
  const pp1 = shiftPerpendicular(p1, p2, p1, offset);
  const pp2 = shiftPerpendicular(p1, p2, p2, offset);

  const dashArray = toDashArray(style.lineStyle);
  const fillColor = style.fill ?? 'rgba(41, 98, 255, 0.05)';

  return (
    <g>
      {/* Fill polygon between the two parallel lines */}
      <polygon
        points={`${p1.x},${p1.y} ${p2.x},${p2.y} ${pp2.x},${pp2.y} ${pp1.x},${pp1.y}`}
        fill={fillColor}
        stroke="none"
      />
      {/* Main line (P1âP2) */}
      <line
        x1={p1.x}
        y1={p1.y}
        x2={p2.x}
        y2={p2.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
      {/* Parallel line */}
      <line
        x1={pp1.x}
        y1={pp1.y}
        x2={pp2.x}
        y2={pp2.y}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
    </g>
  );
}

/**
 * Compute pixel Y coordinate for a price at a given time using regression metadata.
 * Returns the Y pixel position, or null if conversion fails.
 */
function regressionY(
  time: number,
  meta: RegressionMetadata,
  _chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
): number | null {
  const price = meta.intercept + meta.slope * time;
  return mainSeries.priceToCoordinate(price);
}

/**
 * Render a regression channel: median (regression line) + upper/lower bands
 * at Â±kÂ·std from the regression line. The two points define the time range.
 */
function renderRegressionChannel(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  drawing: DrawingObject,
  chartApi: IChartApi,
  mainSeries: ISeriesApi<MainSeriesType>,
) {
  if (points.length < 2) return null;
  const meta = drawing.metadata as RegressionMetadata | undefined;
  if (!meta) return null;

  const p1 = chartToPixel(points[0]!, chartApi, mainSeries);
  const p2 = chartToPixel(points[1]!, chartApi, mainSeries);
  if (!p1 || !p2) return null;

  const t1 = points[0]!.time;
  const t2 = points[1]!.time;
  const { slope, intercept, std, k } = meta;

  // Compute pixel positions for median, upper, lower at both time endpoints
  const medianY1 = regressionY(t1, meta, chartApi, mainSeries);
  const medianY2 = regressionY(t2, meta, chartApi, mainSeries);
  if (medianY1 === null || medianY2 === null) return null;

  // Upper/lower band prices at both endpoints
  const upperPrice1 = intercept + slope * t1 + k * std;
  const upperPrice2 = intercept + slope * t2 + k * std;
  const lowerPrice1 = intercept + slope * t1 - k * std;
  const lowerPrice2 = intercept + slope * t2 - k * std;

  const upperY1 = mainSeries.priceToCoordinate(upperPrice1);
  const upperY2 = mainSeries.priceToCoordinate(upperPrice2);
  const lowerY1 = mainSeries.priceToCoordinate(lowerPrice1);
  const lowerY2 = mainSeries.priceToCoordinate(lowerPrice2);
  if (upperY1 === null || upperY2 === null || lowerY1 === null || lowerY2 === null) return null;

  const x1 = p1.x;
  const x2 = p2.x;
  const dashArray = toDashArray(style.lineStyle);
  const fillColor = style.fill ?? 'rgba(41, 98, 255, 0.05)';

  return (
    <g>
      {/* Fill between upper and lower bands */}
      <polygon
        points={`${x1},${upperY1} ${x2},${upperY2} ${x2},${lowerY2} ${x1},${lowerY1}`}
        fill={fillColor}
        stroke="none"
      />
      {/* Median (regression) line */}
      <line
        x1={x1}
        y1={medianY1}
        x2={x2}
        y2={medianY2}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
      />
      {/* Upper band */}
      <line
        x1={x1}
        y1={upperY1}
        x2={x2}
        y2={upperY2}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
        opacity={0.7}
      />
      {/* Lower band */}
      <line
        x1={x1}
        y1={lowerY1}
        x2={x2}
        y2={lowerY2}
        stroke={style.color}
        strokeWidth={style.lineWidth}
        strokeDasharray={dashArray}
        opacity={0.7}
      />
    </g>
  );
}

/**
 * Render a standard error channel: same as regression channel but band width
 * uses standard error instead of standard deviation.
 */
function renderStandardErrorChannel(
  points: DrawingPoint[],
  style: DrawingObject['style'],
  drawing: DrawingObject,
