/**
 * Chart module type definitions.
 * All domain types for the chart workspace: symbols, bars, quotes,
 * indicators, drawings, layouts, settings, and boundary types.
 */

// âââ Timeframe ââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ

export const TIMEFRAMES = [
  '1s', '5s', '10s', '15s', '30s',
  '1m', '3m', '5m', '10m', '15m', '30m', '45m',
  '1h', '2h', '3h', '4h',
  '1D', '1W', '1M', '3M', '6M', '12M',
  'range', 'tick', 'custom',
] as const;
export type Timeframe = (typeof TIMEFRAMES)[number];

/** Timeframe group classification */
export type TimeframeGroup = 'seconds' | 'minutes' | 'hours' | 'days' | 'range' | 'custom';

/** Timeframe status â drives toolbar/menu rendering and click behavior */
export type TimeframeStatus = 'supported' | 'placeholder' | 'premium';

/** Rich descriptor for a timeframe entry, consumed by toolbar and menus */
export interface TimeframeDescriptor {
  id: Timeframe;
  label: string;
  group: TimeframeGroup;
  /** Sort order within its group (lower = first) */
  sortOrder: number;
  /** Whether this timeframe shows as a direct button in the toolbar row */
  visibleInToolbar: boolean;
  /** Whether the timeframe has seeded data / server support */
  status: TimeframeStatus;
  /** Keyboard shortcut hint (display only) */
  shortcutHint?: string;
}

/**
 * Full timeframe registry with descriptors.
 * Components should use this for rendering the timeframe selector and overflow menus.
 * TIMEFRAMES array above remains the canonical type union source.
 */
export const TIMEFRAME_REGISTRY: readonly TimeframeDescriptor[] = [
  // ââ Seconds ââ
  { id: '1s', label: '1s', group: 'seconds', sortOrder: 10, visibleInToolbar: false, status: 'placeholder' },
  { id: '5s', label: '5s', group: 'seconds', sortOrder: 20, visibleInToolbar: false, status: 'placeholder' },
  { id: '10s', label: '10s', group: 'seconds', sortOrder: 30, visibleInToolbar: false, status: 'placeholder' },
  { id: '15s', label: '15s', group: 'seconds', sortOrder: 40, visibleInToolbar: false, status: 'placeholder' },
  { id: '30s', label: '30s', group: 'seconds', sortOrder: 50, visibleInToolbar: false, status: 'placeholder' },
  // ââ Minutes ââ
  { id: '1m', label: '1m', group: 'minutes', sortOrder: 60, visibleInToolbar: true, status: 'supported' },
  { id: '3m', label: '3m', group: 'minutes', sortOrder: 70, visibleInToolbar: false, status: 'placeholder' },
  { id: '5m', label: '5m', group: 'minutes', sortOrder: 80, visibleInToolbar: true, status: 'supported' },
  { id: '10m', label: '10m', group: 'minutes', sortOrder: 90, visibleInToolbar: false, status: 'placeholder' },
  { id: '15m', label: '15m', group: 'minutes', sortOrder: 100, visibleInToolbar: true, status: 'supported' },
  { id: '30m', label: '30m', group: 'minutes', sortOrder: 110, visibleInToolbar: false, status: 'placeholder' },
  { id: '45m', label: '45m', group: 'minutes', sortOrder: 120, visibleInToolbar: false, status: 'placeholder' },
  // ââ Hours ââ
  { id: '1h', label: '1H', group: 'hours', sortOrder: 130, visibleInToolbar: true, status: 'supported' },
  { id: '2h', label: '2H', group: 'hours', sortOrder: 140, visibleInToolbar: false, status: 'placeholder' },
  { id: '3h', label: '3H', group: 'hours', sortOrder: 150, visibleInToolbar: false, status: 'placeholder' },
  { id: '4h', label: '4H', group: 'hours', sortOrder: 160, visibleInToolbar: false, status: 'placeholder' },
  // ââ Days+ ââ
  { id: '1D', label: '1D', group: 'days', sortOrder: 170, visibleInToolbar: true, status: 'supported' },
  { id: '1W', label: '1W', group: 'days', sortOrder: 180, visibleInToolbar: true, status: 'supported' },
  { id: '1M', label: '1M', group: 'days', sortOrder: 190, visibleInToolbar: true, status: 'supported' },
  { id: '3M', label: '3M', group: 'days', sortOrder: 200, visibleInToolbar: false, status: 'placeholder' },
  { id: '6M', label: '6M', group: 'days', sortOrder: 210, visibleInToolbar: false, status: 'placeholder' },
  { id: '12M', label: '12M', group: 'days', sortOrder: 220, visibleInToolbar: false, status: 'placeholder' },
  // ââ Range / Tick / Custom ââ
  { id: 'range', label: 'Range', group: 'range', sortOrder: 230, visibleInToolbar: false, status: 'premium' },
  { id: 'tick', label: 'Tick', group: 'range', sortOrder: 240, visibleInToolbar: false, status: 'premium' },
  { id: 'custom', label: 'Custom', group: 'custom', sortOrder: 250, visibleInToolbar: false, status: 'premium' },
] as const;

/** Compact subset of timeframes shown directly in the toolbar row */
export const TOOLBAR_TIMEFRAMES: readonly Timeframe[] = TIMEFRAME_REGISTRY
  .filter((t) => t.visibleInToolbar)
  .map((t) => t.id);

/** Overflow timeframes accessible from a menu (not shown directly in toolbar) */
export const OVERFLOW_TIMEFRAMES: readonly Timeframe[] = TIMEFRAME_REGISTRY
  .filter((t) => !t.visibleInToolbar)
  .map((t) => t.id);

/** Lookup a timeframe descriptor by its id */
export function getTimeframeDescriptor(id: Timeframe): TimeframeDescriptor | undefined {
  return TIMEFRAME_REGISTRY.find((t) => t.id === id);
}

/** Get all timeframes in a given group, preserving sortOrder */
export function getTimeframesByGroup(group: TimeframeGroup): readonly TimeframeDescriptor[] {
  return TIMEFRAME_REGISTRY.filter((t) => t.group === group);
}

