/**
 * Linear regression utilities for channel drawing tools.
 *
 * computeLinearRegression fits a least-squares line through a set of
 * (time, close) data points and returns the slope, intercept, and
 * two band-width measures (standard deviation of residuals and
 * standard error of the regression). Channel tools use these to
 * draw the median line and Â±kÂ·width bands.
 */

import type { MarketBar } from '@features/chart/types';

export interface RegressionResult {
  /** Slope of the least-squares line (price units per time unit) */
  slope: number;
  /** Intercept of the regression line at time=0 */
  intercept: number;
  /** Standard deviation of residuals (used by regression_channel) */
  std: number;
  /** Standard error of the regression (used by standard_error_channel) */
  stdError: number;
}

/**
 * Compute the price predicted by the regression line at a given time.
 * price = intercept + slope * time
 */
export function regressionPrice(result: RegressionResult, time: number): number {
  return result.intercept + result.slope * time;
}

/**
 * Compute linear regression on candle close prices within a time range.
 *
 * @param bars  Candle data sorted by timestamp ascending
 * @param t1    Start time (inclusive) of the regression window
 * @param t2    End time (inclusive) of the regression window
 * @returns     Regression result with slope, intercept, std, stdError
 *
 * If fewer than 2 bars are found in the range, returns a fallback
 * result derived from the two endpoint prices.
 */
export function computeLinearRegression(
  bars: MarketBar[],
  t1: number,
  t2: number,
): RegressionResult {
  // Filter bars in the time range
  const lo = Math.min(t1, t2);
  const hi = Math.max(t1, t2);
  const inRange = bars.filter((b) => b.timestamp >= lo && b.timestamp <= hi);

  // Need at least 2 points for regression
  if (inRange.length < 2) {
    // Fallback: use the two endpoint prices from the bar data
    // (or the closest bars) to construct a simple line
    const firstBar = inRange[0] ?? bars.find((b) => b.timestamp >= lo);
    const lastBar = inRange[inRange.length - 1] ?? bars.findLast((b) => b.timestamp <= hi);
    if (firstBar && lastBar && lastBar.timestamp !== firstBar.timestamp) {
      const slope = (lastBar.close - firstBar.close) / (lastBar.timestamp - firstBar.timestamp);
      const intercept = firstBar.close - slope * firstBar.timestamp;
      return { slope, intercept, std: 0, stdError: 0 };
    }
    return { slope: 0, intercept: 0, std: 0, stdError: 0 };
  }

  // Least-squares linear regression: y = intercept + slope * x
  // where x = timestamp, y = close
  const n = inRange.length;
  let sumX = 0;
  let sumY = 0;
  let sumXY = 0;
  let sumX2 = 0;

  for (const bar of inRange) {
    const x = bar.timestamp;
    const y = bar.close;
    sumX += x;
    sumY += y;
    sumXY += x * y;
    sumX2 += x * x;
  }

  const denom = n * sumX2 - sumX * sumX;
  let slope: number;
  let intercept: number;

  if (Math.abs(denom) < 1e-12) {
    // All timestamps are the same (shouldn't happen with â¥2 bars)
    slope = 0;
    intercept = sumY / n;
  } else {
    slope = (n * sumXY - sumX * sumY) / denom;
    intercept = (sumY - slope * sumX) / n;
  }

  // Compute residuals and standard deviation
  let sumResiduals2 = 0;
  for (const bar of inRange) {
    const predicted = intercept + slope * bar.timestamp;
    const residual = bar.close - predicted;
    sumResiduals2 += residual * residual;
  }

  // Standard deviation of residuals (population)
  const std = Math.sqrt(sumResiduals2 / n);

  // Standard error of the regression = sqrt(SSE / (n - 2))
  // For n=2, stdError = 0 (two points define a line exactly)
  const stdError = n > 2 ? Math.sqrt(sumResiduals2 / (n - 2)) : 0;

  return { slope, intercept, std, stdError };
}
